        "Create a token: name it Horizon Nav, leave the public scopes ticked and the secret ones unticked, then paste it below." to "Create a token: Horizon Nav എന്ന് പേരിടുക, പബ്ലിക് സ്കോപ്പുകൾ ടിക്ക് ചെയ്തും രഹസ്യ സ്കോപ്പുകൾ ടിക്ക് ചെയ്യാതെയും വിടുക, എന്നിട്ട് താഴെ പേസ്റ്റ് ചെയ്യുക.",
        "Horizon Nav now draws its map with Mapbox. Your free Mapbox key adds the 3D map with buildings, trees and lane markings, " to "Horizon Nav ഇപ്പോൾ Mapbox ഉപയോഗിച്ചാണ് മാപ്പ് വരയ്ക്കുന്നത്. നിങ്ങളുടെ സൗജന്യ Mapbox കീ കെട്ടിടങ്ങളും മരങ്ങളും ലെയ്ൻ അടയാളങ്ങളുമുള്ള 3D മാപ്പ് ചേർക്കുന്നു, ",
        "live traffic on your route, and better search and speed limits." to "നിങ്ങളുടെ റൂട്ടിലെ തത്സമയ ട്രാഫിക്, മികച്ച തിരയലും വേഗപരിധികളും.",
        "Get it at account.mapbox.com › Tokens: copy the Default public token (it starts pk.)." to "account.mapbox.com › Tokens ൽ നിന്ന് നേടുക: Default public token പകർത്തുക (അത് pk. ൽ ആരംഭിക്കുന്നു).",
        "That's a secret token: use the public one (pk.) here." to "അതൊരു രഹസ്യ ടോക്കണാണ്: ഇവിടെ പബ്ലിക് ടോക്കൺ (pk.) ഉപയോഗിക്കുക.",
        "That doesn't look like a whole token yet: it's a long code starting pk." to "അത് ഇതുവരെ ഒരു മുഴുവൻ ടോക്കൺ ആയി തോന്നുന്നില്ല: pk. ൽ ആരംഭിക്കുന്ന ഒരു നീണ്ട കോഡാണ് അത്.",
        "Part of that token looks missing or mistyped. Copy it again with the copy button at account.mapbox.com › Tokens." to "ആ ടോക്കണിന്റെ ഒരു ഭാഗം കാണാനില്ലാത്തതോ തെറ്റായി ടൈപ്പ് ചെയ്തതോ ആയി തോന്നുന്നു. account.mapbox.com › Tokens ലെ കോപ്പി ബട്ടൺ ഉപയോഗിച്ച് വീണ്ടും പകർത്തുക.",
        "Installed with AAEnabler: Update saves the new version to your Downloads, so you can install it with AAEnabler and keep it in Android Auto." to "AAEnabler ഉപയോഗിച്ച് ഇൻസ്റ്റാൾ ചെയ്തത്: അപ്ഡേറ്റ് പുതിയ പതിപ്പ് നിങ്ങളുടെ ഡൗൺലോഡുകളിൽ സംരക്ഷിക്കുന്നു, അതിനാൽ AAEnabler ഉപയോഗിച്ച് ഇൻസ്റ്റാൾ ചെയ്ത് Android Auto-യിൽ നിലനിർത്താം.",
        "Installed with AAEnabler (or similar)? Updating here takes it out of Android Auto: install the new version with AAEnabler again afterwards." to "AAEnabler (അല്ലെങ്കിൽ സമാനമായത്) ഉപയോഗിച്ച് ഇൻസ്റ്റാൾ ചെയ്തതാണോ? ഇവിടെ അപ്ഡേറ്റ് ചെയ്താൽ അത് Android Auto-യിൽ നിന്ന് പുറത്താകും: അതിനുശേഷം പുതിയ പതിപ്പ് വീണ്ടും AAEnabler ഉപയോഗിച്ച് ഇൻസ്റ്റാൾ ചെയ്യുക.",
        "{0} isn't working right now, so {1} is being used instead" to "{0} ഇപ്പോൾ പ്രവർത്തിക്കുന്നില്ല, അതിനാൽ പകരം {1} ഉപയോഗിക്കുന്നു",
        "Mapbox refused the map for a moment, but your token is fine" to "Mapbox ഒരു നിമിഷത്തേക്ക് മാപ്പ് നിരസിച്ചു, എന്നാൽ നിങ്ങളുടെ ടോക്കൺ ശരിയാണ്",
        "Mapbox accepts your token but keeps refusing the map. Sign in at account.mapbox.com and look for a notice about your account." to "Mapbox നിങ്ങളുടെ ടോക്കൺ സ്വീകരിക്കുന്നു, പക്ഷേ മാപ്പ് നിരസിച്ചുകൊണ്ടിരിക്കുന്നു. account.mapbox.com ൽ സൈൻ ഇൻ ചെയ്ത് നിങ്ങളുടെ അക്കൗണ്ടിനെക്കുറിച്ചുള്ള അറിയിപ്പ് നോക്കുക.",
        "Mapbox search didn't work: {0}" to "Mapbox തിരയൽ പ്രവർത്തിച്ചില്ല: {0}",
        "Carrying on to {0}" to "{0} ലേക്ക് തുടരുന്നു",
        "No voice for directions: install or turn on a text-to-speech engine (Settings > Sound & voice > Voice and language)" to "നിർദ്ദേശങ്ങൾക്ക് ശബ്ദമില്ല: ഒരു ടെക്സ്റ്റ്-ടു-സ്പീച്ച് എഞ്ചിൻ ഇൻസ്റ്റാൾ ചെയ്യുകയോ ഓണാക്കുകയോ ചെയ്യുക (ക്രമീകരണങ്ങൾ > ശബ്ദവും വോയ്സും > വോയ്സും ഭാഷയും)",
        "The text-to-speech voice has no language installed, so directions can't be spoken. Add one in Settings > Sound & voice > Voice and language" to "ടെക്സ്റ്റ്-ടു-സ്പീച്ച് വോയ്സിൽ ഭാഷയൊന്നും ഇൻസ്റ്റാൾ ചെയ്തിട്ടില്ല, അതിനാൽ നിർദ്ദേശങ്ങൾ പറയാനാകില്ല. ക്രമീകരണങ്ങൾ > ശബ്ദവും വോയ്സും > വോയ്സും ഭാഷയും എന്നതിൽ ഒന്ന് ചേർക്കുക",
        "Offline pack ready" to "ഓഫ്‌ലൈൻ പായ്ക്ക് തയ്യാറാണ്",
        "Mapbox won't let this token show the map (403). At account.mapbox.com › Tokens, edit it: tick all the public scopes and remove any URL restrictions." to "ഈ ടോക്കൺ ഉപയോഗിച്ച് മാപ്പ് കാണിക്കാൻ Mapbox അനുവദിക്കുന്നില്ല (403). account.mapbox.com › Tokens ൽ അത് എഡിറ്റ് ചെയ്യുക: എല്ലാ പബ്ലിക് സ്കോപ്പുകളും ടിക്ക് ചെയ്ത് URL നിയന്ത്രണങ്ങൾ നീക്കം ചെയ്യുക.",
        "The map couldn't make a secure connection. Check the head unit's date and time are right." to "മാപ്പിന് സുരക്ഷിത കണക്ഷൻ ഉണ്ടാക്കാനായില്ല. ഹെഡ് യൂണിറ്റിലെ തീയതിയും സമയവും ശരിയാണോ എന്ന് പരിശോധിക്കുക.",
        "Map: {0}" to "മാപ്പ്: {0}",
        "No signal for the map: trying again…" to "മാപ്പിന് സിഗ്നൽ ഇല്ല: വീണ്ടും ശ്രമിക്കുന്നു…",
        "Add your Mapbox access token (it starts pk.) in Settings > Keys & accounts to show the map" to "മാപ്പ് കാണിക്കാൻ ക്രമീകരണങ്ങൾ > കീകളും അക്കൗണ്ടുകളും എന്നതിൽ നിങ്ങളുടെ Mapbox ആക്സസ് ടോക്കൺ (pk. ൽ ആരംഭിക്കുന്നത്) ചേർക്കുക",
        "Satellite view needs a connection: showing the downloaded map until it's back" to "സാറ്റലൈറ്റ് കാഴ്ചയ്ക്ക് കണക്ഷൻ വേണം: അത് തിരികെ വരുന്നതുവരെ ഡൗൺലോഡ് ചെയ്ത മാപ്പ് കാണിക്കുന്നു",
        "Location permission is needed for navigation" to "നാവിഗേഷന് ലൊക്കേഷൻ അനുമതി ആവശ്യമാണ്",
        "Stop added: {0}" to "സ്റ്റോപ്പ് ചേർത്തു: {0}",
        "That stretch is too short to avoid" to "ആ ഭാഗം ഒഴിവാക്കാൻ വളരെ ചെറുതാണ്",
        "No GPS fix yet" to "ഇതുവരെ GPS ലഭിച്ചിട്ടില്ല",
        "Nothing to avoid ahead" to "മുന്നിൽ ഒഴിവാക്കാൻ ഒന്നുമില്ല",
        "Looking for a way round…" to "മറ്റൊരു വഴി തിരയുന്നു…",
        "Allow Horizon Nav to install updates, then tap Update again" to "അപ്ഡേറ്റുകൾ ഇൻസ്റ്റാൾ ചെയ്യാൻ Horizon Nav-നെ അനുവദിക്കുക, എന്നിട്ട് വീണ്ടും അപ്ഡേറ്റ് ടാപ്പ് ചെയ്യുക",
        "The head unit's date and time look wrong. Set them right in its settings: until then, maps, search and routes can't connect even with signal." to "ഹെഡ് യൂണിറ്റിലെ തീയതിയും സമയവും തെറ്റാണെന്ന് തോന്നുന്നു. അതിന്റെ ക്രമീകരണങ്ങളിൽ ശരിയാക്കുക: അതുവരെ സിഗ്നൽ ഉണ്ടെങ്കിലും മാപ്പുകൾക്കും തിരയലിനും റൂട്ടുകൾക്കും കണക്റ്റ് ചെയ്യാനാകില്ല.",
    )

