        "No signal: showing saved places and offline towns" to "സിഗ്നൽ ഇല്ല: സംരക്ഷിച്ച സ്ഥലങ്ങളും ഓഫ്‌ലൈൻ പട്ടണങ്ങളും കാണിക്കുന്നു",
        "Weak signal: showing saved places and offline towns" to "ദുർബലമായ സിഗ്നൽ: സംരക്ഷിച്ച സ്ഥലങ്ങളും ഓഫ്‌ലൈൻ പട്ടണങ്ങളും കാണിക്കുന്നു",
        "To plan routes, add a free TomTom key or Mapbox token in Settings > Keys & accounts, or download the offline pack" to "റൂട്ടുകൾ ആസൂത്രണം ചെയ്യാൻ, ക്രമീകരണങ്ങൾ > കീകളും അക്കൗണ്ടുകളും എന്നതിൽ സൗജന്യ TomTom കീയോ Mapbox ടോക്കണോ ചേർക്കുക, അല്ലെങ്കിൽ ഓഫ്‌ലൈൻ പായ്ക്ക് ഡൗൺലോഡ് ചെയ്യുക",
        "No GPS fix yet: routing from the map centre. Use the demo drive to simulate." to "ഇതുവരെ GPS ലഭിച്ചിട്ടില്ല: മാപ്പിന്റെ മധ്യത്തിൽ നിന്ന് റൂട്ട് ചെയ്യുന്നു. സിമുലേറ്റ് ചെയ്യാൻ ഡെമോ ഡ്രൈവ് ഉപയോഗിക്കുക.",
        "Your downloaded map ends before {0}: the route goes to the edge of it for now, and the rest is planned as soon as there's signal" to "നിങ്ങൾ ഡൗൺലോഡ് ചെയ്ത മാപ്പ് {0} ന് മുമ്പ് അവസാനിക്കുന്നു: ഇപ്പോൾ റൂട്ട് അതിന്റെ അറ്റം വരെ പോകുന്നു, ബാക്കി സിഗ്നൽ ലഭിക്കുമ്പോൾ ആസൂത്രണം ചെയ്യും",
        "Offline route: no traffic or live data" to "ഓഫ്‌ലൈൻ റൂട്ട്: ട്രാഫിക്കോ തത്സമയ ഡാറ്റയോ ഇല്ല",
        "Departure time not supported here: showing live traffic" to "ഇവിടെ പുറപ്പെടൽ സമയം പിന്തുണയ്ക്കുന്നില്ല: തത്സമയ ട്രാഫിക് കാണിക്കുന്നു",
        "Couldn't find a way round the areas you're avoiding, so the route goes through them" to "നിങ്ങൾ ഒഴിവാക്കുന്ന പ്രദേശങ്ങൾ ചുറ്റിപ്പോകാൻ വഴി കണ്ടെത്താനായില്ല, അതിനാൽ റൂട്ട് അവയിലൂടെ പോകുന്നു",
        "No signal: this route will start by itself as soon as there is a connection" to "സിഗ്നൽ ഇല്ല: കണക്ഷൻ ലഭിച്ചാലുടൻ ഈ റൂട്ട് സ്വയം ആരംഭിക്കും",
        "Route failed: {0}" to "റൂട്ട് പരാജയപ്പെട്ടു: {0}",
