        "No alternative routes. Switch on 'Alternatives' first." to "മറ്റ് റൂട്ടുകളില്ല. ആദ്യം 'മറ്റ് റൂട്ടുകൾ' ഓണാക്കുക.",
        "Rerouting…" to "റൂട്ട് പുനഃക്രമീകരിക്കുന്നു…",
