        "Could not find \"{0}\"" to "\"{0}\" കണ്ടെത്താനായില്ല",
        "Search failed: {0}" to "തിരയൽ പരാജയപ്പെട്ടു: {0}",
        "No position yet" to "ഇതുവരെ സ്ഥാനം ലഭിച്ചിട്ടില്ല",
        "Search took too long. Check the signal and try again." to "തിരയലിന് വളരെ സമയമെടുത്തു. സിഗ്നൽ പരിശോധിച്ച് വീണ്ടും ശ്രമിക്കുക.",
        "Nothing found along the route ahead" to "മുന്നിലുള്ള റൂട്ടിൽ ഒന്നും കണ്ടെത്തിയില്ല",
        "This is now your default zoom. Change or reset it in Settings > Map style" to "ഇതാണ് ഇപ്പോൾ നിങ്ങളുടെ ഡിഫോൾട്ട് സൂം. ക്രമീകരണങ്ങൾ > മാപ്പ് ശൈലി എന്നതിൽ മാറ്റുകയോ റീസെറ്റ് ചെയ്യുകയോ ചെയ്യാം",
        "Pair with your car first: Settings > Places & trips" to "ആദ്യം നിങ്ങളുടെ കാറുമായി ജോടിയാക്കുക: ക്രമീകരണങ്ങൾ > സ്ഥലങ്ങളും യാത്രകളും",
