        "Pick a destination first, then start the demo drive" to "ആദ്യം ഒരു ലക്ഷ്യസ്ഥാനം തിരഞ്ഞെടുക്കുക, എന്നിട്ട് ഡെമോ ഡ്രൈവ് ആരംഭിക്കുക",
