        "Traffic, lights, cameras, signs, weather" to "ട്രാഫിക്, ലൈറ്റുകൾ, ക്യാമറകൾ, ബോർഡുകൾ, കാലാവസ്ഥ",
        "Your arrow & route line" to "നിങ്ങളുടെ ആരോയും റൂട്ട് ലൈനും",
