        "Offline maps" to "ഓഫ്‌ലൈൻ മാപ്പുകൾ",
        "Maps, routes and town names with no signal" to "സിഗ്നൽ ഇല്ലാതെ മാപ്പുകളും റൂട്ടുകളും പട്ടണങ്ങളുടെ പേരുകളും",
        "Screen & sizes" to "സ്ക്രീനും വലുപ്പങ്ങളും",
