        "Car-screen sizes and setting it up" to "കാർ സ്ക്രീൻ വലുപ്പങ്ങളും സജ്ജീകരണവും",
        "Performance" to "പ്രകടനം",
        "Smoothness on slower head units, demo" to "വേഗം കുറഞ്ഞ ഹെഡ് യൂണിറ്റുകളിൽ സുഗമത, ഡെമോ",
        "Keys & accounts" to "കീകളും അക്കൗണ്ടുകളും",
        "Map keys and search" to "മാപ്പ് കീകളും തിരയലും",
        "About & backup" to "വിവരവും ബാക്കപ്പും",
        "Feedback, updates, permissions, backup" to "ഫീഡ്ബാക്ക്, അപ്ഡേറ്റുകൾ, അനുമതികൾ, ബാക്കപ്പ്",
        "Back to the map" to "മാപ്പിലേക്ക് മടങ്ങുക",
        "Search settings" to "ക്രമീകരണങ്ങൾ തിരയുക",
        "Nothing matches \"{0}\"" to "\"{0}\" ന് പൊരുത്തമൊന്നുമില്ല",
        "All settings" to "എല്ലാ ക്രമീകരണങ്ങളും",
        "Headlights" to "ഹെഡ്‌ലൈറ്റുകൾ",
        "Sun times" to "സൂര്യ സമയങ്ങൾ",
        "My times" to "എന്റെ സമയങ്ങൾ",
        "Auto follows the head unit's own night mode once it has switched to it, and sunrise and sunset until then. Headlights follows the head unit's night mode when it switches with your lights (turn on its headlight or illumination night-mode option), with sun times until then. Sun times switches at sunrise and sunset. My times switches at the times you set" to "ഹെഡ് യൂണിറ്റ് സ്വന്തം രാത്രി മോഡിലേക്ക് മാറിക്കഴിഞ്ഞാൽ ഓട്ടോ അതിനെ പിന്തുടരും, അതുവരെ സൂര്യോദയവും സൂര്യാസ്തമയവും. നിങ്ങളുടെ ലൈറ്റുകൾക്കൊപ്പം ഹെഡ് യൂണിറ്റ് രാത്രി മോഡിലേക്ക് മാറുമ്പോൾ ഹെഡ്‌ലൈറ്റുകൾ അതിനെ പിന്തുടരും (അതിന്റെ ഹെഡ്‌ലൈറ്റ് അല്ലെങ്കിൽ ഇല്യൂമിനേഷൻ രാത്രി-മോഡ് ഓപ്ഷൻ ഓണാക്കുക), അതുവരെ സൂര്യ സമയങ്ങൾ. സൂര്യ സമയങ്ങൾ സൂര്യോദയത്തിലും സൂര്യാസ്തമയത്തിലും മാറുന്നു. എന്റെ സമയങ്ങൾ നിങ്ങൾ സജ്ജമാക്കുന്ന സമയങ്ങളിൽ മാറുന്നു",
        "Night starts at" to "രാത്രി ആരംഭിക്കുന്നത്",
        "24-hour clock, for example 19:30" to "24 മണിക്കൂർ ക്ലോക്ക്, ഉദാഹരണത്തിന് 19:30",
        "Day starts at" to "പകൽ ആരംഭിക്കുന്നത്",
        "24-hour clock, for example 06:45" to "24 മണിക്കൂർ ക്ലോക്ക്, ഉദാഹരണത്തിന് 06:45",
        "Colours" to "നിറങ്ങൾ",
        "Car's lighting colour" to "കാറിന്റെ ലൈറ്റിംഗ് നിറം",
        "The map, mostly at night, takes a hint of it" to "മാപ്പിന്, കൂടുതലും രാത്രിയിൽ, അതിന്റെ ഒരു ഛായ ലഭിക്കുന്നു",
        "How strong" to "എത്ര ശക്തമായി",
        "How much of the colour the map takes" to "മാപ്പ് എത്രത്തോളം നിറം എടുക്കുന്നു",
        "The map" to "മാപ്",
        "Map source" to "മാപ്പ് ഉറവിടം",
        "Mapbox: the 3D map. TomTom: TomTom's map in the Horizon colours (needs a TomTom key). All need the Mapbox token, as Mapbox's engine draws them" to "Mapbox: 3D മാപ്പ്. TomTom: Horizon നിറങ്ങളിൽ TomTom-ന്റെ മാപ്പ് (TomTom കീ ആവശ്യമാണ്). Mapbox-ന്റെ എഞ്ചിനാണ് അവ വരയ്ക്കുന്നത്, അതിനാൽ എല്ലാത്തിനും Mapbox ടോക്കൺ ആവശ്യമാണ്",
        "Map detail" to "മാപ്പ് വിശദാംശം",
        "Full 3D" to "പൂർണ്ണ 3D",
        "Lite" to "ലൈറ്റ്",
        "Lightest" to "ഏറ്റവും ലൈറ്റ്",
        "Full 3D: buildings, landmarks, trees and shadows. Lite: flat buildings, no landmarks or shadows. Lightest: Mapbox's simpler 2D map, for slow head units" to "പൂർണ്ണ 3D: കെട്ടിടങ്ങൾ, അടയാള സ്ഥലങ്ങൾ, മരങ്ങൾ, നിഴലുകൾ. ലൈറ്റ്: പരന്ന കെട്ടിടങ്ങൾ, അടയാള സ്ഥലങ്ങളോ നിഴലുകളോ ഇല്ല. ഏറ്റവും ലൈറ്റ്: വേഗം കുറഞ്ഞ ഹെഡ് യൂണിറ്റുകൾക്കായി Mapbox-ന്റെ ലളിതമായ 2D മാപ്പ്",
        "Footpaths and trails" to "നടപ്പാതകളും ട്രെയിലുകളും",
        "Turn off for a cleaner driving map" to "കൂടുതൽ വൃത്തിയുള്ള ഡ്രൈവിംഗ് മാപ്പിന് ഓഫാക്കുക",
        "Light and weather" to "വെളിച്ചവും കാലാവസ്ഥയും",
        "Night brightness" to "രാത്രി തെളിച്ചം",
        "How bright the whole night map is. 100% is Mapbox's own night light" to "രാത്രി മാപ്പ് മുഴുവൻ എത്ര തെളിച്ചമുള്ളതാണ്. 100% Mapbox-ന്റെ സ്വന്തം രാത്രി വെളിച്ചമാണ്",
        "Moonlight at night" to "രാത്രി നിലാവ്",
        "Like dusk, but from the moon: a low blue light with long soft shadows, in place of Mapbox's flat night light. The night sky and your colours stay" to "സന്ധ്യ പോലെ, എന്നാൽ ചന്ദ്രനിൽ നിന്ന്: Mapbox-ന്റെ പരന്ന രാത്രി വെളിച്ചത്തിന് പകരം നീണ്ട മൃദുവായ നിഴലുകളുള്ള താഴ്ന്ന നീല വെളിച്ചം. രാത്രി ആകാശവും നിങ്ങളുടെ നിറങ്ങളും നിലനിൽക്കും",
        "Moon strength" to "ചന്ദ്രന്റെ ശക്തി",
        "How strongly the moon lights walls and casts shadows" to "ചന്ദ്രൻ ചുവരുകളെ എത്ര ശക്തമായി പ്രകാശിപ്പിക്കുകയും നിഴൽ വീഴ്ത്തുകയും ചെയ്യുന്നു",
        "Shadows" to "നിഴലുകൾ",
        "Buildings and trees cast shadows. Off is also lighter work for a slow head unit" to "കെട്ടിടങ്ങളും മരങ്ങളും നിഴൽ വീഴ്ത്തുന്നു. ഓഫാക്കുന്നത് വേഗം കുറഞ്ഞ ഹെഡ് യൂണിറ്റിന് ഭാരം കുറയ്ക്കും",
        "Sun in its real place" to "സൂര്യൻ അതിന്റെ യഥാർത്ഥ സ്ഥാനത്ത്",
        "By day, the light and shadows come from where the sun really is right now" to "പകൽ, വെളിച്ചവും നിഴലുകളും ഇപ്പോൾ സൂര്യൻ യഥാർത്ഥത്തിൽ എവിടെയാണോ അവിടെ നിന്ന് വരുന്നു",
        "Overcast light" to "മേഘാവൃത വെളിച്ചം",
        "Soft daylight with no hard shadows, calmer in glare" to "കടുത്ത നിഴലുകളില്ലാത്ത മൃദുവായ പകൽവെളിച്ചം, തിളക്കം കുറവ്",
        "Weather light" to "കാലാവസ്ഥ വെളിച്ചം",
        "A greyer, softer daylight when it's raining or snowing where you are. Needs Weather effects on the map switched on (Settings > On the map), which also brings real rain and snow" to "നിങ്ങൾ ഉള്ളിടത്ത് മഴയോ മഞ്ഞോ പെയ്യുമ്പോൾ കൂടുതൽ ചാരനിറമുള്ള, മൃദുവായ പകൽവെളിച്ചം. മാപ്പിലെ കാലാവസ്ഥ ഇഫക്റ്റുകൾ ഓണാക്കണം (ക്രമീകരണങ്ങൾ > മാപ്പിൽ), അത് യഥാർത്ഥ മഴയും മഞ്ഞും കൊണ്ടുവരും",
        "3D view" to "3D കാഴ്ച",
        "30° to 65°. Auto is the app's own choice (54°, or 52° with a lighter map). Tilt with speed and flattening at turns still work on top." to "30° മുതൽ 65° വരെ. ഓട്ടോ ആപ്പിന്റെ സ്വന്തം തിരഞ്ഞെടുപ്പാണ് (54°, അല്ലെങ്കിൽ ലൈറ്റ് മാപ്പിൽ 52°). വേഗത്തിനനുസരിച്ചുള്ള ചരിവും തിരിവുകളിൽ പരന്നതാക്കലും അതിനുമുകളിൽ പ്രവർത്തിക്കും.",
        "Tilt on a wide screen" to "വീതിയുള്ള സ്ക്രീനിൽ ചരിവ്",
        "Landscape head units. Higher shows further ahead (more for a slow unit to draw)" to "ലാൻഡ്‌സ്കേപ്പ് ഹെഡ് യൂണിറ്റുകൾ. കൂടുതൽ ഉയരത്തിൽ കൂടുതൽ ദൂരം കാണാം (വേഗം കുറഞ്ഞ യൂണിറ്റിന് വരയ്ക്കാൻ കൂടുതൽ)",
        "Tilt on a tall screen" to "ഉയരമുള്ള സ്ക്രീനിൽ ചരിവ്",
        "Portrait screens and phones" to "പോർട്രെയിറ്റ് സ്ക്രീനുകളും ഫോണുകളും",
        "Tilt on Android Auto" to "Android Auto-യിൽ ചരിവ്",
        "The car screen" to "കാർ സ്ക്രീൻ",
        "Hill shading" to "കുന്നുകളുടെ ഷേഡിംഗ്",
        "Soft shading on hillsides, so valleys and ridges show even on a flat map. Lighter work than 3D hills" to "കുന്നിൻചരിവുകളിൽ മൃദുവായ ഷേഡിംഗ്, അതിനാൽ പരന്ന മാപ്പിലും താഴ്വരകളും മലനിരകളും കാണാം. 3D കുന്നുകളേക്കാൾ ഭാരം കുറവ്",
        "Detailed building fronts" to "വിശദമായ കെട്ടിട മുഖങ്ങൾ",
        "Windows, doors and shopfronts on buildings, where Mapbox has them (mostly city centres)" to "Mapbox-ൽ ഉള്ളിടത്ത് കെട്ടിടങ്ങളിൽ ജനലുകളും വാതിലുകളും കടമുഖങ്ങളും (കൂടുതലും നഗരകേന്ദ്രങ്ങളിൽ)",
        "3D landmarks" to "3D അടയാള സ്ഥലങ്ങൾ",
        "Detailed models of well-known buildings, bridges and stadiums" to "പ്രശസ്തമായ കെട്ടിടങ്ങളുടെയും പാലങ്ങളുടെയും സ്റ്റേഡിയങ്ങളുടെയും വിശദമായ മോഡലുകൾ",
        "3D hills and valleys" to "3D കുന്നുകളും താഴ്വാരങ്ങളും",
        "Real terrain. Lovely in hilly areas, but harder work for a slow head unit" to "യഥാർത്ഥ ഭൂപ്രകൃതി. കുന്നിൻപ്രദേശങ്ങളിൽ മനോഹരം, പക്ഷേ വേഗം കുറഞ്ഞ ഹെഡ് യൂണിറ്റിന് കൂടുതൽ ഭാരം",
        "Trees in parks" to "പാർക്കുകളിലെ മരങ്ങൾ",
        "Mapbox's 3D trees in parks and along streets" to "പാർക്കുകളിലും തെരുവുകളിലും Mapbox-ന്റെ 3D മരങ്ങൾ",
        "Keep the road ahead clear" to "മുന്നിലെ റോഡ് വ്യക്തമായി സൂക്ഷിക്കുക",
        "Mapbox's 3D trees and landmarks are left out round your arrow and, on a route, along the middle of the road just ahead, so they never hide it" to "Mapbox-ന്റെ 3D മരങ്ങളും അടയാള സ്ഥലങ്ങളും നിങ്ങളുടെ ആരോയ്ക്ക് ചുറ്റും, റൂട്ടിലായിരിക്കുമ്പോൾ തൊട്ടുമുന്നിലെ റോഡിന്റെ നടുവിലും ഒഴിവാക്കുന്നു, അതിനാൽ അവ ഒരിക്കലും അതിനെ മറയ്ക്കില്ല",
        "Tap to highlight" to "ഹൈലൈറ്റ് ചെയ്യാൻ ടാപ്പ് ചെയ്യുക",
        "Tap a building to light it up; tap a shop or place, then hold on it to go there" to "ഒരു കെട്ടിടം പ്രകാശിപ്പിക്കാൻ അതിൽ ടാപ്പ് ചെയ്യുക; ഒരു കടയിലോ സ്ഥലത്തോ ടാപ്പ് ചെയ്ത്, അവിടേക്ക് പോകാൻ അതിൽ അമർത്തിപ്പിടിക്കുക",
        "Sky and satellite" to "ആകാശവും സാറ്റലൈറ്റും",
        "Fog and sky" to "മൂടൽമഞ്ഞും ആകാശവും",
        "Haze towards the horizon to match the weather: grey when overcast, thicker in rain, thick in fog" to "കാലാവസ്ഥയ്ക്ക് അനുസരിച്ച് ചക്രവാളത്തിലേക്ക് മൂടൽ: മേഘാവൃതമാകുമ്പോൾ ചാരനിറം, മഴയിൽ കട്ടിയുള്ളത്, മൂടൽമഞ്ഞിൽ കനത്തത്",
        "Night sky in 3D" to "3D-യിൽ രാത്രി ആകാശം",
        "Twinkling stars above the horizon after dark" to "ഇരുട്ടിയതിനുശേഷം ചക്രവാളത്തിന് മുകളിൽ മിന്നുന്ന നക്ഷത്രങ്ങൾ",
        "Holding on the map" to "മാപ്പിൽ അമർത്തിപ്പിടിക്കൽ",
        "What's here" to "ഇവിടെ എന്താണ്",
        "Holding on the map shows the road, its speed limit and the area first, with Go and Add as a stop. Off goes straight there, as before" to "മാപ്പിൽ അമർത്തിപ്പിടിച്ചാൽ ആദ്യം റോഡും അതിന്റെ വേഗപരിധിയും പ്രദേശവും പോകുക, സ്റ്റോപ്പായി ചേർക്കുക എന്നിവയോടെ കാണിക്കും. ഓഫ് ആണെങ്കിൽ പഴയതുപോലെ നേരിട്ട് അവിടേക്ക് പോകും",
        "Live traffic" to "തത്സമയ ട്രാഫിക്",
        "Traffic overview when stopped" to "നിർത്തിയിരിക്കുമ്പോൾ ട്രാഫിക് അവലോകനം",
        "After 30 seconds stopped (lights, a queue), the map pulls back to a top-down view of the traffic round you, and back again when you move off" to "30 സെക്കൻഡ് നിർത്തിയിട്ടതിനുശേഷം (സിഗ്നൽ, ക്യൂ), മാപ്പ് നിങ്ങൾക്ക് ചുറ്റുമുള്ള ട്രാഫിക്കിന്റെ മുകളിൽ നിന്നുള്ള കാഴ്ചയിലേക്ക് മാറും, നിങ്ങൾ നീങ്ങുമ്പോൾ തിരികെ വരും",
        "Only show traffic on your route while navigating" to "നാവിഗേറ്റ് ചെയ്യുമ്പോൾ നിങ്ങളുടെ റൂട്ടിലെ ട്രാഫിക് മാത്രം കാണിക്കുക",
        "Off shows traffic on the roads around you too, as Google Maps does" to "ഓഫ് ആണെങ്കിൽ Google Maps പോലെ നിങ്ങൾക്ക് ചുറ്റുമുള്ള റോഡുകളിലെ ട്രാഫിക്കും കാണിക്കും",
        "Light traffic in green" to "കുറഞ്ഞ ട്രാഫിക് പച്ചയിൽ",
        "Free-flowing main roads shown green, as well as slow traffic in amber and red" to "സുഗമമായ പ്രധാന റോഡുകൾ പച്ചയിൽ, കൂടാതെ മന്ദഗതിയിലുള്ള ട്രാഫിക് ഓറഞ്ചിലും ചുവപ്പിലും",
        "Only the ones on your route. Now: " to "നിങ്ങളുടെ റൂട്ടിലുള്ളവ മാത്രം. ഇപ്പോൾ: ",
        "Speed cameras and roadworks" to "സ്പീഡ് ക്യാമറകളും റോഡ് പണികളും",
        "Their icons on the map. The warnings are in Settings > Alerts" to "മാപ്പിൽ അവയുടെ ഐക്കണുകൾ. മുന്നറിയിപ്പുകൾ ക്രമീകരണങ്ങൾ > മുന്നറിയിപ്പുകൾ എന്നതിലാണ്",
        "Speed camera size" to "സ്പീഡ് ക്യാമറയുടെ വലുപ്പം",
        "The red camera badge on the map" to "മാപ്പിലെ ചുവന്ന ക്യാമറ ബാഡ്ജ്",
        "Zebra crossings" to "സീബ്ര ക്രോസിംഗുകൾ",
        "Crossings on your route painted on the road, with Belisha beacons at zebras (close in)" to "നിങ്ങളുടെ റൂട്ടിലെ ക്രോസിംഗുകൾ റോഡിൽ വരച്ച്, സീബ്രകളിൽ ബെലിഷ ബീക്കണുകളോടെ (അടുത്ത് സൂം ചെയ്യുമ്പോൾ)",
        "Stop signs" to "സ്റ്റോപ്പ് ബോർഡുകൾ",
        "Stop signs on your route shown on the map, with a short chime before each one (where OpenStreetMap has them)" to "നിങ്ങളുടെ റൂട്ടിലെ സ്റ്റോപ്പ് ബോർഡുകൾ മാപ്പിൽ കാണിക്കുന്നു, ഓരോന്നിനും മുമ്പ് ചെറിയൊരു മണിനാദത്തോടെ (OpenStreetMap-ൽ ഉള്ളിടത്ത്)",
        "Number-plate cameras" to "നമ്പർ പ്ലേറ്റ് ക്യാമറകൾ",
        "Flock and other automatic number-plate cameras mapped on OpenStreetMap. Shown on the map only, no alerts" to "OpenStreetMap-ൽ അടയാളപ്പെടുത്തിയ Flock-ഉം മറ്റ് ഓട്ടോമാറ്റിക് നമ്പർ പ്ലേറ്റ് ക്യാമറകളും. മാപ്പിൽ മാത്രം കാണിക്കുന്നു, മുന്നറിയിപ്പുകളില്ല",
        "3D street furniture" to "3D തെരുവ് ഉപകരണങ്ങൾ",
        "3D street lamps, traffic lights and cameras" to "3D തെരുവുവിളക്കുകൾ, ട്രാഫിക് ലൈറ്റുകൾ, ക്യാമറകൾ",
        "Real-size 3D models with lit lamps and lights (Full 3D). Off: the simpler badges and blocks" to "കത്തുന്ന വിളക്കുകളും ലൈറ്റുകളുമുള്ള യഥാർത്ഥ വലുപ്പ 3D മോഡലുകൾ (പൂർണ്ണ 3D). ഓഫ്: ലളിതമായ ബാഡ്ജുകളും ബ്ലോക്കുകളും",
        "Now: " to "ഇപ്പോൾ: ",
        "Street lamp spacing" to "തെരുവുവിളക്കുകൾ തമ്മിലുള്ള അകലം",
        "Weather effects on the map" to "മാപ്പിലെ കാലാവസ്ഥ ഇഫക്റ്റുകൾ",
        "Real rain and snow falling on the map (and fog) to match the weather where you are" to "നിങ്ങൾ ഉള്ളിടത്തെ കാലാവസ്ഥയ്ക്ക് അനുസരിച്ച് മാപ്പിൽ യഥാർത്ഥ മഴയും മഞ്ഞും (മൂടൽമഞ്ഞും)",
        "Rain radar layer" to "മഴ റഡാർ ലെയർ",
        "Live radar from RainViewer, under the route" to "റൂട്ടിന് താഴെ RainViewer-ൽ നിന്നുള്ള തത്സമയ റഡാർ",
        "Your arrow" to "നിങ്ങളുടെ ആരോ",
        "Real 3D model: drawn in the map itself, lit and shadowed like the buildings (Full 3D only; otherwise the picture of the same shape is used). The 3D arrow and car are pictures of 3D shapes. The flat arrow is the lightest to draw on a slow unit." to "യഥാർത്ഥ 3D മോഡൽ: മാപ്പിൽ തന്നെ വരയ്ക്കുന്നു, കെട്ടിടങ്ങൾ പോലെ വെളിച്ചവും നിഴലും (പൂർണ്ണ 3D മാത്രം; അല്ലെങ്കിൽ അതേ ആകൃതിയുടെ ചിത്രം ഉപയോഗിക്കും). 3D ആരോയും കാറും 3D ആകൃതികളുടെ ചിത്രങ്ങളാണ്. വേഗം കുറഞ്ഞ യൂണിറ്റിൽ വരയ്ക്കാൻ ഏറ്റവും ലഘുവായത് പരന്ന ആരോയാണ്.",
        "Couldn't read that picture (try a PNG or JPG)" to "ആ ചിത്രം വായിക്കാനായില്ല (PNG അല്ലെങ്കിൽ JPG ശ്രമിക്കുക)",
        "No app on this unit can pick a picture (try installing a file manager or gallery)" to "ഈ യൂണിറ്റിൽ ചിത്രം തിരഞ്ഞെടുക്കാൻ ആപ്പില്ല (ഒരു ഫയൽ മാനേജറോ ഗാലറിയോ ഇൻസ്റ്റാൾ ചെയ്തു നോക്കുക)",
        "Locator" to "സ്ഥാന സൂചകം",
        "3D arrow" to "3D ആരോ",
        "Car" to "കാർ",
        "Real 3D model" to "യഥാർത്ഥ 3D മോഡൽ",
        "Flat arrow" to "പരന്ന ആരോ",
        "Your picture" to "നിങ്ങളുടെ ചിത്രം",
        "Model shape" to "മോഡലിന്റെ ആകൃതി",
        "Arrow" to "ആരോ",
        "Glow" to "തിളക്കം",
        "A soft blue glow round the model, and the model lit up brightly" to "മോഡലിന് ചുറ്റും മൃദുവായ നീല തിളക്കം, മോഡൽ തെളിച്ചത്തോടെ പ്രകാശിക്കുന്നു",
        "The real 3D model shows with Map detail: Full 3D. On Lite and Lightest the picture of the same shape is used." to "മാപ്പ് വിശദാംശം: പൂർണ്ണ 3D ആയിരിക്കുമ്പോൾ യഥാർത്ഥ 3D മോഡൽ കാണിക്കും. ലൈറ്റിലും ഏറ്റവും ലൈറ്റിലും അതേ ആകൃതിയുടെ ചിത്രം ഉപയോഗിക്കും.",
        "Picture" to "ചിത്രം",
        "A PNG with a see-through background looks best. Point the top of it the way you drive" to "സുതാര്യമായ പശ്ചാത്തലമുള്ള PNG ആണ് ഏറ്റവും നല്ലത്. അതിന്റെ മുകൾഭാഗം നിങ്ങൾ ഓടിക്കുന്ന ദിശയിലേക്ക് വയ്ക്കുക",
        "Choose" to "തിരഞ്ഞെടുക്കുക",
        "Turns with you" to "നിങ്ങളോടൊപ്പം തിരിയുന്നു",
        "Lies flat on the road and turns as you drive, like the arrow. Off keeps it upright" to "ആരോ പോലെ റോഡിൽ പരന്നുകിടന്ന് നിങ്ങൾ ഓടിക്കുമ്പോൾ തിരിയുന്നു. ഓഫ് ആണെങ്കിൽ നിവർന്നുനിൽക്കും",
        "Round crop" to "വൃത്താകൃതിയിൽ മുറിക്കുക",
        "Cuts it to a circle with a white edge (good for photos)" to "വെളുത്ത അരികുള്ള വൃത്തമായി മുറിക്കുന്നു (ഫോട്ടോകൾക്ക് നല്ലത്)",
        "Saloon" to "സെഡാൻ",
        "Hatchback" to "ഹാച്ച്ബാക്ക്",
        "Estate" to "എസ്റ്റേറ്റ്",
        "Pickup" to "പിക്കപ്പ്",
        "Van" to "വാൻ",
        "Sports" to "സ്പോർട്സ്",
        "Car type" to "കാർ തരം",
        "Car colour" to "കാറിന്റെ നിറം",
        "White" to "വെള്ള",
        "Silver" to "വെള്ളി",
        "Grey" to "ചാരനിറം",
        "Graphite" to "ഗ്രാഫൈറ്റ്",
        "Black" to "കറുപ്പ്",
        "Navy" to "നേവി",
        "Blue" to "നീല",
        "Sky blue" to "ആകാശനീല",
        "Teal" to "ടീൽ",
        "Green" to "പച്ച",
        "Olive" to "ഒലിവ്",
        "Yellow" to "മഞ്ഞ",
        "Orange" to "ഓറഞ്ച്",
        "Red" to "ചുവപ്പ്",
        "Burgundy" to "ബർഗണ്ടി",
