        "Rename" to "പേരുമാറ്റുക",
        "Favourites" to "പ്രിയപ്പെട്ടവ",
        "No favourites yet. Tap the star on a destination to add one." to "ഇതുവരെ പ്രിയപ്പെട്ടവയില്ല. ഒന്ന് ചേർക്കാൻ ഒരു ലക്ഷ്യസ്ഥാനത്തിലെ നക്ഷത്രത്തിൽ ടാപ്പ് ചെയ്യുക.",
        "Make {0}…" to "{0} ആക്കുക…",
        "{0} is now Home" to "{0} ഇപ്പോൾ വീടാണ്",
        "{0} is now Work" to "{0} ഇപ്പോൾ ജോലിസ്ഥലമാണ്",
        "Make Home / Work" to "വീട് / ജോലിസ്ഥലം ആക്കുക",
        "Remove every favourite" to "എല്ലാ പ്രിയപ്പെട്ടവയും നീക്കം ചെയ്യുക",
        "Remove all" to "എല്ലാം നീക്കം ചെയ്യുക",
        "History" to "ചരിത്രം",
        "Swipe a place sideways on the Saved & recent list to take it off." to "സംരക്ഷിച്ചവയും സമീപകാലവും പട്ടികയിൽ ഒരു സ്ഥലം നീക്കം ചെയ്യാൻ അത് വശത്തേക്ക് സ്വൈപ്പ് ചെയ്യുക.",
        "Saved & recent under the search bar" to "തിരയൽ ബാറിന് താഴെ സംരക്ഷിച്ചവയും സമീപകാലവും",
        "The list of favourites and recent places on the map" to "മാപ്പിൽ പ്രിയപ്പെട്ടവയുടെയും സമീപകാല സ്ഥലങ്ങളുടെയും പട്ടിക",
        "Recent destinations" to "സമീപകാലത്തു പോയ സ്ഥലങ്ങൾ",
        "{0} recent, plus places remembered for searching without signal" to "{0} സമീപകാലം, കൂടാതെ സിഗ്നൽ ഇല്ലാതെ തിരയാൻ ഓർമ്മിച്ച സ്ഥലങ്ങളും",
        "History cleared" to "ചരിത്രം മായ്ച്ചു",
        "Trip log" to "യാത്രാ ലോഗ്",
        "No trips yet. Every drive is recorded here when you park." to "ഇതുവരെ യാത്രകളില്ല. നിങ്ങൾ പാർക്ക് ചെയ്യുമ്പോൾ ഓരോ ഡ്രൈവും ഇവിടെ രേഖപ്പെടുത്തും.",
        " in all" to " ആകെ",
        "{0} · moving {1} · top {2} {3}" to "{0} · നീങ്ങിയത് {1} · ഉയർന്നത് {2} {3}",
        "Default zoom" to "ഡിഫോൾട്ട് സൂം",
        "When you're not on a route. Auto zoom still pulls out at speed and moves in at junctions, round your setting. Or zoom with + and − on the map and tap \"Make this my default\"" to "നിങ്ങൾ റൂട്ടിലല്ലാത്തപ്പോൾ. ഓട്ടോ സൂം നിങ്ങളുടെ ക്രമീകരണത്തെ ആധാരമാക്കി വേഗത്തിൽ പുറത്തേക്കും ജംഗ്ഷനുകളിൽ അകത്തേക്കും സൂം ചെയ്യും. അല്ലെങ്കിൽ മാപ്പിലെ +, − ഉപയോഗിച്ച് സൂം ചെയ്ത് \"ഇത് എന്റെ ഡിഫോൾട്ട് ആക്കുക\" ടാപ്പ് ചെയ്യുക",
        "Further out" to "കൂടുതൽ ദൂരെ",
        "Closer" to "കൂടുതൽ അടുത്ത്",
        "Send places from your phone" to "ഫോണിൽ നിന്ന് സ്ഥലങ്ങൾ അയയ്ക്കുക",
        "Pair once: on the head unit, tap Pair a phone and type its code into Horizon Nav on your phone (in this same place). Then \"Send to car\" on the phone's route screen sends the place to the head unit, which starts it the next time it's on (within 12 hours). Places go through ntfy.sh, a free message relay, scrambled with your code so only your phone and car can read them." to "ഒരിക്കൽ ജോടിയാക്കുക: ഹെഡ് യൂണിറ്റിൽ, ഫോൺ ജോടിയാക്കുക ടാപ്പ് ചെയ്ത് അതിന്റെ കോഡ് നിങ്ങളുടെ ഫോണിലെ Horizon Nav-ൽ (ഇതേ സ്ഥലത്ത്) ടൈപ്പ് ചെയ്യുക. പിന്നീട് ഫോണിന്റെ റൂട്ട് സ്ക്രീനിലെ \"കാറിലേക്ക് അയയ്ക്കുക\" സ്ഥലം ഹെഡ് യൂണിറ്റിലേക്ക് അയയ്ക്കും, അടുത്ത തവണ ഓണാകുമ്പോൾ (12 മണിക്കൂറിനുള്ളിൽ) അത് ആരംഭിക്കും. സ്ഥലങ്ങൾ സൗജന്യ സന്ദേശ റിലേയായ ntfy.sh വഴി പോകുന്നു, നിങ്ങളുടെ ഫോണിനും കാറിനും മാത്രം വായിക്കാനാകുന്ന വിധം നിങ്ങളുടെ കോഡ് ഉപയോഗിച്ച് എൻക്രിപ്റ്റ് ചെയ്തിരിക്കുന്നു.",
        "This is the car" to "ഇതാണ് കാർ",
        "Paired. Code {0}: type it on another phone to add it too" to "ജോടിയാക്കി. കോഡ് {0}: മറ്റൊരു ഫോണും ചേർക്കാൻ അതിൽ ഇത് ടൈപ്പ് ചെയ്യുക",
        "Unpair" to "ജോടി മാറ്റുക",
        "The pairing code as a QR code" to "ജോടിയാക്കൽ കോഡ് QR കോഡായി",
        "This is your phone" to "ഇതാണ് നിങ്ങളുടെ ഫോൺ",
        "Paired with your car ({0}). \"Send to car\" is on the route screen, next to Save" to "നിങ്ങളുടെ കാറുമായി ജോടിയാക്കി ({0}). \"കാറിലേക്ക് അയയ്ക്കുക\" റൂട്ട് സ്ക്രീനിൽ സംരക്ഷിക്കുക എന്നതിന് അടുത്താണ്",
        "On the head unit" to "ഹെഡ് യൂണിറ്റിൽ",
        "Makes a code to type on your phone" to "ഫോണിൽ ടൈപ്പ് ചെയ്യാൻ ഒരു കോഡ് ഉണ്ടാക്കുന്നു",
        "Pair a phone" to "ഫോൺ ജോടിയാക്കുക",
        "On your phone" to "നിങ്ങളുടെ ഫോണിൽ",
        "Type the code the head unit shows" to "ഹെഡ് യൂണിറ്റ് കാണിക്കുന്ന കോഡ് ടൈപ്പ് ചെയ്യുക",
        "Enter code" to "കോഡ് നൽകുക",
        "Car's code" to "കാറിന്റെ കോഡ്",
        "Like K7P-4QX-M2D" to "K7P-4QX-M2D പോലെ",
        "Share your ETA" to "എത്തുന്ന സമയം പങ്കിടുക",
        "The share button on the trip card texts your arrival time and a map link. On a head unit without a SIM it opens your messaging app instead." to "യാത്രാ കാർഡിലെ പങ്കിടൽ ബട്ടൺ നിങ്ങളുടെ എത്തുന്ന സമയവും മാപ്പ് ലിങ്കും സന്ദേശമായി അയയ്ക്കുന്നു. SIM ഇല്ലാത്ത ഹെഡ് യൂണിറ്റിൽ പകരം നിങ്ങളുടെ സന്ദേശ ആപ്പ് തുറക്കും.",
        "Send it to" to "ഇതിലേക്ക് അയയ്ക്കുക",
        "No one chosen yet" to "ഇതുവരെ ആരെയും തിരഞ്ഞെടുത്തിട്ടില്ല",
        "Places from other apps" to "മറ്റ് ആപ്പുകളിൽ നിന്നുള്ള സ്ഥലങ്ങൾ",
        "Share a place to Horizon Nav from Google Maps, WhatsApp, Contacts or a web page and it plans the route. To open Google Maps links here straight away, tap Open by default and add the links." to "Google Maps, WhatsApp, കോൺടാക്റ്റുകൾ അല്ലെങ്കിൽ ഒരു വെബ് പേജിൽ നിന്ന് Horizon Nav-ലേക്ക് ഒരു സ്ഥലം പങ്കിടുക, അത് റൂട്ട് ആസൂത്രണം ചെയ്യും. Google Maps ലിങ്കുകൾ ഇവിടെ നേരിട്ട് തുറക്കാൻ, ഡിഫോൾട്ടായി തുറക്കുക ടാപ്പ് ചെയ്ത് ലിങ്കുകൾ ചേർക്കുക.",
        "Google Maps links" to "Google Maps ലിങ്കുകൾ",
        "Open by default" to "ഡിഫോൾട്ടായി തുറക്കുക",
        "Fuel prices" to "ഇന്ധന വിലകൾ",
        "Live prices come from the government's Fuel Finder scheme. It's free: on gov.uk search \"Fuel Finder\", register as an information recipient with a GOV.UK One Login, then paste the client ID and secret here. Without them the fuel list still works, just without prices." to "തത്സമയ വിലകൾ സർക്കാരിന്റെ Fuel Finder പദ്ധതിയിൽ നിന്നാണ്. ഇത് സൗജന്യമാണ്: gov.uk-ൽ \"Fuel Finder\" തിരയുക, GOV.UK One Login ഉപയോഗിച്ച് വിവര സ്വീകർത്താവായി രജിസ്റ്റർ ചെയ്യുക, എന്നിട്ട് client ID-യും secret-ഉം ഇവിടെ പേസ്റ്റ് ചെയ്യുക. ഇവ ഇല്ലെങ്കിലും ഇന്ധന പട്ടിക പ്രവർത്തിക്കും, വിലകൾ ഇല്ലാതെ.",
        "Your fuel" to "നിങ്ങളുടെ ഇന്ധനം",
        "Unleaded" to "അൺലെഡഡ്",
        "Super" to "സൂപ്പർ",
        "Diesel" to "ഡീസൽ",
        "Bioethanol (E85)" to "ബയോഎഥനോൾ (E85)",
        "Electric" to "ഇലക്ട്രിക്",
        "Suggest a fuel stop on long trips" to "ദീർഘ യാത്രകളിൽ ഇന്ധനം നിറയ്ക്കാൻ നിർദേശിക്കുക",
        "Over about 95 miles" to "ഏകദേശം 95 മൈലിൽ കൂടുതൽ",
        "Over about 150 km" to "ഏകദേശം 150 കി.മീ-ൽ കൂടുതൽ",
        ", a charging point along the way with the shortest detour" to ", ഏറ്റവും കുറഞ്ഞ വഴിമാറ്റമുള്ള വഴിയിലെ ചാർജിംഗ് പോയിന്റ്",
        ", the best-value station along the way" to ", വഴിയിലെ ഏറ്റവും മികച്ച വിലയുള്ള സ്റ്റേഷൻ",
        "Client ID" to "Client ID",
        "Client secret" to "Client secret",
        "Prices" to "വിലകൾ",
        "Add your details first" to "ആദ്യം നിങ്ങളുടെ വിവരങ്ങൾ ചേർക്കുക",
        "Update now" to "ഇപ്പോൾ അപ്ഡേറ്റ് ചെയ്യുക",
        "Downloading stations and prices (the first time takes a minute)…" to "സ്റ്റേഷനുകളും വിലകളും ഡൗൺലോഡ് ചെയ്യുന്നു (ആദ്യ തവണ ഒരു മിനിറ്റ് എടുക്കും)…",
        "Spotted a wrong price?" to "തെറ്റായ വില കണ്ടോ?",
        "Report it" to "റിപ്പോർട്ട് ചെയ്യുക",
        "Fuel prices outside the UK" to "UK-ക്ക് പുറത്തുള്ള ഇന്ധന വിലകൾ",
        "France and Austria work by themselves, from their governments' own price services. Germany needs a free key from creativecommons.tankerkoenig.de (Tankerkönig). Australia (NSW and Tasmania) needs a free API key and secret from api.nsw.gov.au (Fuel API). Prices show in cents a litre, e.g. 189.9c. Elsewhere the fuel list still works, without prices." to "ഫ്രാൻസും ഓസ്ട്രിയയും സർക്കാരുകളുടെ സ്വന്തം വില സേവനങ്ങളിൽ നിന്ന് സ്വയം പ്രവർത്തിക്കും. ജർമ്മനിക്ക് creativecommons.tankerkoenig.de (Tankerkönig) ൽ നിന്ന് സൗജന്യ കീ വേണം. ഓസ്ട്രേലിയയ്ക്ക് (NSW, ടാസ്മാനിയ) api.nsw.gov.au (Fuel API) ൽ നിന്ന് സൗജന്യ API കീയും secret-ഉം വേണം. വിലകൾ ലിറ്ററിന് സെന്റിൽ കാണിക്കും, ഉദാ. 189.9c. മറ്റിടങ്ങളിൽ ഇന്ധന പട്ടിക വിലകളില്ലാതെ പ്രവർത്തിക്കും.",
        "Tankerkönig key (Germany)" to "Tankerkönig കീ (ജർമ്മനി)",
        "Paste the key" to "കീ പേസ്റ്റ് ചെയ്യുക",
        "FuelCheck API key (Australia)" to "FuelCheck API കീ (ഓസ്ട്രേലിയ)",
        "New South Wales and Tasmania" to "ന്യൂ സൗത്ത് വെയിൽസും ടാസ്മാനിയയും",
        "Paste the API key" to "API കീ പേസ്റ്റ് ചെയ്യുക",
        "FuelCheck API secret" to "FuelCheck API secret",
        "Paste the API secret" to "API secret പേസ്റ്റ് ചെയ്യുക",
        "Your electric car" to "നിങ്ങളുടെ ഇലക്ട്രിക് കാർ",
        "With the efficiency and price filled in, each route shows roughly what it will cost to charge for. The efficiency and battery size also give the battery estimate on the trip card and the charging stop suggestions (set your battery level on the route options)." to "കാര്യക്ഷമതയും വിലയും പൂരിപ്പിച്ചാൽ, ഓരോ റൂട്ടിനും ചാർജ് ചെയ്യാൻ ഏകദേശം എത്ര ചെലവാകുമെന്ന് കാണിക്കും. കാര്യക്ഷമതയും ബാറ്ററി വലുപ്പവും യാത്രാ കാർഡിലെ ബാറ്ററി കണക്കും ചാർജിംഗ് സ്റ്റോപ്പ് നിർദ്ദേശങ്ങളും നൽകുന്നു (റൂട്ട് ഓപ്ഷനുകളിൽ ബാറ്ററി നില സജ്ജമാക്കുക).",
        "Battery estimate on the trip card" to "യാത്രാ കാർഡിൽ ബാറ്ററി കണക്ക്",
        "Roughly how much battery you'll arrive with, on the phone and Android Auto. It's worked out from your settings, not read from the car" to "ഫോണിലും Android Auto-യിലും നിങ്ങൾ ഏകദേശം എത്ര ബാറ്ററിയോടെ എത്തുമെന്ന്. ഇത് കാറിൽ നിന്ന് വായിക്കുന്നതല്ല, നിങ്ങളുടെ ക്രമീകരണങ്ങളിൽ നിന്ന് കണക്കാക്കുന്നതാണ്",
        "Show petrol stations too" to "പെട്രോൾ സ്റ്റേഷനുകളും കാണിക്കുക",
        "The Fuel button on the map page (on the phone and Android Auto). Off: Charging takes its place" to "മാപ്പ് പേജിലെ ഇന്ധന ബട്ടൺ (ഫോണിലും Android Auto-യിലും). ഓഫ്: പകരം ചാർജിംഗ് വരും",
        "Efficiency (miles per kWh)" to "കാര്യക്ഷമത (kWh-ന് മൈൽ)",
        "e.g. 3.5" to "ഉദാ. 3.5",
        "Efficiency (km per kWh)" to "കാര്യക്ഷമത (kWh-ന് കി.മീ)",
