        "If Horizon Nav doesn't appear in Android Auto: 1. Open Android Auto's settings, tap the version number at the bottom about 10 times, then in the top-right menu open Developer settings and turn on Unknown sources. 2. Back in Android Auto's settings, open Customise launcher and make sure Horizon Nav is ticked. 3. Force stop Android Auto (App info below), unplug and plug back in. If it still doesn't show, your phone's Android Auto only lists apps installed by the Play Store: install the APK through an installer that sets Play as the source (for example \"adb install -i com.android.vending\", or an app like AAAD or Install with Options)." to "Horizon Nav Android Auto-യിൽ കാണുന്നില്ലെങ്കിൽ: 1. Android Auto-യുടെ ക്രമീകരണങ്ങൾ തുറന്ന്, താഴെയുള്ള പതിപ്പ് നമ്പറിൽ ഏകദേശം 10 തവണ ടാപ്പ് ചെയ്യുക, എന്നിട്ട് മുകളിൽ വലത് മെനുവിൽ ഡെവലപ്പർ ക്രമീകരണങ്ങൾ തുറന്ന് അജ്ഞാത ഉറവിടങ്ങൾ ഓണാക്കുക. 2. Android Auto-യുടെ ക്രമീകരണങ്ങളിൽ തിരികെ വന്ന്, ലോഞ്ചർ ഇഷ്ടാനുസൃതമാക്കുക തുറന്ന് Horizon Nav ടിക്ക് ചെയ്തിട്ടുണ്ടെന്ന് ഉറപ്പാക്കുക. 3. Android Auto നിർബന്ധിച്ച് നിർത്തുക (താഴെയുള്ള ആപ്പ് വിവരം), കേബിൾ ഊരി വീണ്ടും കുത്തുക. ഇപ്പോഴും കാണുന്നില്ലെങ്കിൽ, നിങ്ങളുടെ ഫോണിലെ Android Auto Play Store ഇൻസ്റ്റാൾ ചെയ്ത ആപ്പുകൾ മാത്രമേ ലിസ്റ്റ് ചെയ്യൂ: Play ഉറവിടമായി സജ്ജമാക്കുന്ന ഇൻസ്റ്റാളർ വഴി APK ഇൻസ്റ്റാൾ ചെയ്യുക (ഉദാഹരണത്തിന് \"adb install -i com.android.vending\", അല്ലെങ്കിൽ AAAD, Install with Options പോലുള്ള ആപ്പ്).",
        "Installed by" to "ഇൻസ്റ്റാൾ ചെയ്തത്",
        "Android Auto settings" to "Android Auto ക്രമീകരണങ്ങൾ",
        "Android Auto isn't installed on this phone" to "ഈ ഫോണിൽ Android Auto ഇൻസ്റ്റാൾ ചെയ്തിട്ടില്ല",
        "Android Auto app info" to "Android Auto ആപ്പ് വിവരം",
        "To force stop it after changing its settings" to "അതിന്റെ ക്രമീകരണങ്ങൾ മാറ്റിയശേഷം നിർബന്ധിച്ച് നിർത്താൻ",
        "App info" to "ആപ്പ് വിവരം",
        "Not showing in Android Auto?" to "Android Auto-യിൽ കാണുന്നില്ലേ?",
        "1. In Android Auto's settings, tap Version repeatedly to unlock Developer settings, then turn on Unknown sources. " to "1. Android Auto-യുടെ ക്രമീകരണങ്ങളിൽ, ഡെവലപ്പർ ക്രമീകരണങ്ങൾ അൺലോക്ക് ചെയ്യാൻ പതിപ്പിൽ ആവർത്തിച്ച് ടാപ്പ് ചെയ്യുക, എന്നിട്ട് അജ്ഞാത ഉറവിടങ്ങൾ ഓണാക്കുക. ",
        "2. Force stop Android Auto (App info above) and reconnect. 3. If it still isn't listed, install Horizon Nav with the free AAEnabler app, which most people need. " to "2. Android Auto നിർബന്ധിച്ച് നിർത്തി (മുകളിലുള്ള ആപ്പ് വിവരം) വീണ്ടും കണക്റ്റ് ചെയ്യുക. 3. ഇപ്പോഴും ലിസ്റ്റിൽ ഇല്ലെങ്കിൽ, മിക്കവർക്കും ആവശ്യമായ സൗജന്യ AAEnabler ആപ്പ് ഉപയോഗിച്ച് Horizon Nav ഇൻസ്റ്റാൾ ചെയ്യുക. ",
        "Voice requests through Android Auto's own microphone may not reach apps from outside Google Play: use the app's search button instead." to "Android Auto-യുടെ സ്വന്തം മൈക്രോഫോൺ വഴിയുള്ള ശബ്ദ അഭ്യർത്ഥനകൾ Google Play-ക്ക് പുറത്തുനിന്നുള്ള ആപ്പുകളിൽ എത്തിയേക്കില്ല: പകരം ആപ്പിന്റെ തിരയൽ ബട്ടൺ ഉപയോഗിക്കുക.",
        "No browser on this device: search for AAEnabler on GitHub" to "ഈ ഉപകരണത്തിൽ ബ്രൗസർ ഇല്ല: GitHub-ൽ AAEnabler തിരയുക",
        "Smoothness" to "സുഗമത",
        "Lower these if the map feels slow or the head unit gets warm. Sharpness and fast drawing apply after restarting the app." to "മാപ്പ് മന്ദഗതിയിലാണെന്ന് തോന്നുകയോ ഹെഡ് യൂണിറ്റ് ചൂടാകുകയോ ചെയ്താൽ ഇവ കുറയ്ക്കുക. വ്യക്തതയും വേഗത്തിലുള്ള വരയ്ക്കലും ആപ്പ് പുനരാരംഭിച്ചതിനുശേഷം ബാധകമാകും.",
        "Map sharpness" to "മാപ്പ് വ്യക്തത",
        "Full" to "പൂർണ്ണം",
        "Balanced" to "സന്തുലിതം",
        "Light" to "ലൈറ്റ്",
        "Lowest" to "ഏറ്റവും കുറവ്",
        "Frame rate" to "ഫ്രെയിം നിരക്ക്",
        "Starts at 30 and steps down when the head unit can't keep up, so the map moves evenly" to "30-ൽ ആരംഭിച്ച്, ഹെഡ് യൂണിറ്റിന് ഒപ്പമെത്താനാകാത്തപ്പോൾ കുറയുന്നു, അതിനാൽ മാപ്പ് ഒരേപോലെ നീങ്ങും",
        "Lower is lighter on the head unit" to "കുറവാണെങ്കിൽ ഹെഡ് യൂണിറ്റിന് ഭാരം കുറവ്",
        "Fast map drawing" to "വേഗത്തിലുള്ള മാപ്പ് വരയ്ക്കൽ",
        "Performance meter" to "പ്രകടന മീറ്റർ",
        "A line at the top of the map: frames drawn, camera moves and pauses. Handy for finding what slows the map" to "മാപ്പിന് മുകളിൽ ഒരു വരി: വരച്ച ഫ്രെയിമുകൾ, ക്യാമറ നീക്കങ്ങൾ, ഇടവേളകൾ. മാപ്പിനെ മന്ദഗതിയിലാക്കുന്നത് കണ്ടെത്താൻ ഉപകാരപ്രദം",
        "Demo" to "ഡെമോ",
        "Demo drive button" to "ഡെമോ ഡ്രൈവ് ബട്ടൺ",
        "Plays a route back so you can try the guidance while parked" to "പാർക്ക് ചെയ്തിരിക്കുമ്പോൾ മാർഗ്ഗനിർദ്ദേശം പരീക്ഷിക്കാൻ ഒരു റൂട്ട് പ്ലേ ചെയ്യുന്നു",
        "Search results" to "തിരയൽ ഫലങ്ങൾ",
        "Search with" to "ഇത് ഉപയോഗിച്ച് തിരയുക",
        "TomTom's search is the one Horizon Nav uses: best for UK addresses and house numbers" to "Horizon Nav ഉപയോഗിക്കുന്നത് TomTom-ന്റെ തിരയലാണ്: UK വിലാസങ്ങൾക്കും വീട്ടുനമ്പറുകൾക്കും ഏറ്റവും നല്ലത്",
        "For the most accurate address search, add a free TomTom key below." to "ഏറ്റവും കൃത്യമായ വിലാസ തിരയലിന്, താഴെ ഒരു സൗജന്യ TomTom കീ ചേർക്കുക.",
        "Map accounts" to "മാപ്പ് അക്കൗണ്ടുകൾ",
        "Search also finds places you saved or went to before. With no signal, routes, the map and search come from the offline pack." to "നിങ്ങൾ മുമ്പ് സംരക്ഷിച്ചതോ പോയതോ ആയ സ്ഥലങ്ങളും തിരയൽ കണ്ടെത്തും. സിഗ്നൽ ഇല്ലാത്തപ്പോൾ റൂട്ടുകളും മാപ്പും തിരയലും ഓഫ്‌ലൈൻ പായ്ക്കിൽ നിന്നാണ്.",
        "TomTom API key" to "TomTom API കീ",
        "Using the key built into this app unless you paste another" to "നിങ്ങൾ മറ്റൊന്ന് പേസ്റ്റ് ചെയ്യുന്നില്ലെങ്കിൽ ഈ ആപ്പിൽ ഉൾപ്പെടുത്തിയ കീ ഉപയോഗിക്കുന്നു",
        "Optional: gives the most accurate address search, and a backup for routes and traffic. Free from developer.tomtom.com" to "ഐച്ഛികം: ഏറ്റവും കൃത്യമായ വിലാസ തിരയലും റൂട്ടുകൾക്കും ട്രാഫിക്കിനും ഒരു ബാക്കപ്പും നൽകുന്നു. developer.tomtom.com ൽ നിന്ന് സൗജന്യം",
        "Paste a key" to "ഒരു കീ പേസ്റ്റ് ചെയ്യുക",
        "Mapbox access token" to "Mapbox ആക്സസ് ടോക്കൺ",
        "Use an active public token starting pk. (never sk.). If the map reports 401, open account.mapbox.com > Tokens, copy an active token, and check it has styles:read and fonts:read permissions." to "pk. ൽ ആരംഭിക്കുന്ന സജീവ പബ്ലിക് ടോക്കൺ ഉപയോഗിക്കുക (ഒരിക്കലും sk. അല്ല). മാപ്പ് 401 റിപ്പോർട്ട് ചെയ്താൽ, account.mapbox.com > Tokens തുറന്ന്, ഒരു സജീവ ടോക്കൺ പകർത്തി, അതിന് styles:read, fonts:read അനുമതികൾ ഉണ്ടോയെന്ന് പരിശോധിക്കുക.",
        "Paste a token" to "ഒരു ടോക്കൺ പേസ്റ്റ് ചെയ്യുക",
        "Routes, search and traffic" to "റൂട്ടുകൾ, തിരയൽ, ട്രാഫിക്",
        "Auto uses Mapbox while the Mapbox map is showing, and TomTom otherwise. If the one in use stops working (its daily limit, a refused key, an outage), the other takes over by itself for a while." to "Mapbox മാപ്പ് കാണിക്കുമ്പോൾ ഓട്ടോ Mapbox ഉപയോഗിക്കും, അല്ലാത്തപ്പോൾ TomTom. ഉപയോഗത്തിലുള്ളത് പ്രവർത്തനം നിർത്തിയാൽ (ദൈനംദിന പരിധി, നിരസിച്ച കീ, തകരാർ), മറ്റേത് കുറച്ചുസമയത്തേക്ക് സ്വയം ഏറ്റെടുക്കും.",
        "Use" to "ഉപയോഗിക്കുക",
        "Feedback" to "ഫീഡ്ബാക്ക്",
        "Ideas and bug reports are very welcome, here or on GitHub and Reddit." to "ആശയങ്ങളും ബഗ് റിപ്പോർട്ടുകളും വളരെ സ്വാഗതം, ഇവിടെയോ GitHub-ലും Reddit-ലും.",
        "Feedback or a problem" to "ഫീഡ്ബാക്ക് അല്ലെങ്കിൽ ഒരു പ്രശ്നം",
        "Sends a report with the app version, your unit and the last crash, so it's quick to fix" to "ആപ്പ് പതിപ്പ്, നിങ്ങളുടെ യൂണിറ്റ്, അവസാന ക്രാഷ് എന്നിവയോടെ ഒരു റിപ്പോർട്ട് അയയ്ക്കുന്നു, അതിനാൽ വേഗം പരിഹരിക്കാം",
        "Support Horizon Nav" to "Horizon Nav-നെ പിന്തുണയ്ക്കുക",
        "Donate" to "സംഭാവന നൽകുക",
        "Free, no ads. Donations help keep it going (PayPal)" to "സൗജന്യം, പരസ്യങ്ങളില്ല. സംഭാവനകൾ ഇത് മുന്നോട്ട് കൊണ്ടുപോകാൻ സഹായിക്കുന്നു (PayPal)",
        "Version" to "പതിപ്പ്",
        "Check for updates" to "അപ്ഡേറ്റുകൾക്കായി പരിശോധിക്കുക",
        "Update to {0}" to "{0} ലേക്ക് അപ്ഡേറ്റ് ചെയ്യുക",
        "Check now" to "ഇപ്പോൾ പരിശോധിക്കുക",
        "Look for updates by itself" to "സ്വയം അപ്ഡേറ്റുകൾ തിരയുക",
        "When the app opens and there's a connection (at most every half hour)" to "ആപ്പ് തുറക്കുകയും കണക്ഷൻ ഉണ്ടാകുകയും ചെയ്യുമ്പോൾ (പരമാവധി അര മണിക്കൂറിൽ ഒരിക്കൽ)",
        "Setup" to "സജ്ജീകരണം",
        "Go through the first-run steps again: map key, home and work, offline maps, permissions" to "ആദ്യ ഘട്ടങ്ങൾ വീണ്ടും: മാപ്പ് കീ, വീടും ജോലിസ്ഥലവും, ഓഫ്‌ലൈൻ മാപ്പുകൾ, അനുമതികൾ",
        "Run setup" to "സജ്ജീകരണം പ്രവർത്തിപ്പിക്കുക",
        "Permissions" to "അനുമതികൾ",
        "While a route is running, guidance carries on when you switch apps and a notification shows. Allow notifications so it can appear." to "ഒരു റൂട്ട് പ്രവർത്തിക്കുമ്പോൾ, നിങ്ങൾ ആപ്പുകൾ മാറിയാലും മാർഗ്ഗനിർദ്ദേശം തുടരുകയും ഒരു അറിയിപ്പ് കാണിക്കുകയും ചെയ്യും. അത് പ്രത്യക്ഷപ്പെടാൻ അറിയിപ്പുകൾ അനുവദിക്കുക.",
        "Location" to "ലൊക്കേഷൻ",
        "Allowed" to "അനുവദിച്ചു",
        "Not allowed: navigation needs it" to "അനുവദിച്ചിട്ടില്ല: നാവിഗേഷന് ഇത് ആവശ്യമാണ്",
        "App permissions" to "ആപ്പ് അനുമതികൾ",
        "Location services" to "ലൊക്കേഷൻ സേവനങ്ങൾ",
        "Backup saved" to "ബാക്കപ്പ് സംരക്ഷിച്ചു",
        "Could not save the backup" to "ബാക്കപ്പ് സംരക്ഷിക്കാനായില്ല",
        "Restored {0} settings" to "{0} ക്രമീകരണങ്ങൾ പുനഃസ്ഥാപിച്ചു",
        "That file is not a valid backup" to "ആ ഫയൽ സാധുവായ ബാക്കപ്പ് അല്ല",
        "Backup" to "ബാക്കപ്പ്",
        "Includes settings and saved places, not the API key or the offline pack. A backup from Horizon Launcher can be restored here too." to "ക്രമീകരണങ്ങളും സംരക്ഷിച്ച സ്ഥലങ്ങളും ഉൾപ്പെടുന്നു, API കീയോ ഓഫ്‌ലൈൻ പായ്ക്കോ അല്ല. Horizon Launcher-ൽ നിന്നുള്ള ബാക്കപ്പും ഇവിടെ പുനഃസ്ഥാപിക്കാം.",
        "Settings and saved places" to "ക്രമീകരണങ്ങളും സംരക്ഷിച്ച സ്ഥലങ്ങളും",
        "Back up" to "ബാക്കപ്പ് എടുക്കുക",
