        "Sent with it: the app version, your head unit, the main settings, your downloaded areas and the last crash (no places or API keys)." to "ഇതിനോടൊപ്പം അയയ്ക്കുന്നത്: ആപ്പ് പതിപ്പ്, നിങ്ങളുടെ ഹെഡ് യൂണിറ്റ്, പ്രധാന ക്രമീകരണങ്ങൾ, ഡൗൺലോഡ് ചെയ്ത പ്രദേശങ്ങൾ, അവസാന ക്രാഷ് (സ്ഥലങ്ങളോ API കീകളോ ഇല്ല).",
