        "Report copied: paste it into a message or a Reddit comment" to "റിപ്പോർട്ട് പകർത്തി: ഒരു സന്ദേശത്തിലോ Reddit കമന്റിലോ പേസ്റ്റ് ചെയ്യുക",
        "Send on GitHub" to "GitHub-ൽ അയയ്ക്കുക",
        "Report from Horizon Nav {0}" to "Horizon Nav {0} ൽ നിന്നുള്ള റിപ്പോർട്ട്",
        "No browser on this unit: use Copy instead" to "ഈ യൂണിറ്റിൽ ബ്രൗസർ ഇല്ല: പകരം പകർത്തുക ഉപയോഗിക്കുക",
        "Mono Night" to "മോണോ നൈറ്റ്",
        "High Contrast" to "ഉയർന്ന കോൺട്രാസ്റ്റ്",
        "Match my car" to "എന്റെ കാറിന് അനുസരിച്ച്",
        "Custom" to "ഇഷ്ടാനുസൃതം",
        "Horizon: Mapbox's map in the app's own soft colours, slate blue at night. Twilight: the same with a deeper purple night. Mono Night: greys, with only the route and warnings in colour. Match my car: a hint of your car's interior lighting colour. Custom: your own colours. Day colours shown (Match my car at night); each has a night version" to "Horizon: ആപ്പിന്റെ സ്വന്തം മൃദു നിറങ്ങളിൽ Mapbox-ന്റെ മാപ്പ്, രാത്രിയിൽ സ്ലേറ്റ് നീല. Twilight: അതേപോലെ, കൂടുതൽ ആഴമുള്ള പർപ്പിൾ രാത്രിയോടെ. മോണോ നൈറ്റ്: ചാരനിറങ്ങൾ, റൂട്ടും മുന്നറിയിപ്പുകളും മാത്രം നിറത്തിൽ. എന്റെ കാറിന് അനുസരിച്ച്: നിങ്ങളുടെ കാറിന്റെ ഉൾവശ ലൈറ്റിന്റെ നിറത്തിന്റെ ഒരു ഛായ. ഇഷ്ടാനുസൃതം: നിങ്ങളുടെ സ്വന്തം നിറങ്ങൾ. പകൽ നിറങ്ങൾ കാണിക്കുന്നു (എന്റെ കാറിന് അനുസരിച്ച് രാത്രിയിൽ); ഓരോന്നിനും രാത്രി പതിപ്പുണ്ട്",
        "Live preview" to "തത്സമയ പ്രിവ്യൂ",
        "Custom colours" to "ഇഷ്ടാനുസൃത നിറങ്ങൾ",
        "Changes show on the preview at the top as you make them, and are only kept when you press Save. A part you haven't changed keeps the colour of the theme it starts from. At night the light darkens the colours you pick, as it does every theme." to "നിങ്ങൾ മാറ്റുമ്പോൾ മാറ്റങ്ങൾ മുകളിലെ പ്രിവ്യൂവിൽ കാണാം, സംരക്ഷിക്കുക അമർത്തുമ്പോൾ മാത്രമേ നിലനിർത്തൂ. നിങ്ങൾ മാറ്റാത്ത ഭാഗം ആരംഭിക്കുന്ന തീമിന്റെ നിറം നിലനിർത്തും. എല്ലാ തീമിലും എന്നപോലെ, രാത്രിയിൽ വെളിച്ചം നിങ്ങൾ തിരഞ്ഞെടുക്കുന്ന നിറങ്ങളെ ഇരുണ്ടതാക്കും.",
        "Starts from" to "ഇതിൽ നിന്ന് ആരംഭിക്കുന്നു",
        "The theme your colours go on top of" to "നിങ്ങളുടെ നിറങ്ങൾ ചേർക്കുന്ന തീം",
        "Day colours" to "പകൽ നിറങ്ങൾ",
        "Night colours" to "രാത്രി നിറങ്ങൾ",
        "The route you're following (traffic still shows amber and red)" to "നിങ്ങൾ പിന്തുടരുന്ന റൂട്ട് (ട്രാഫിക് ഇപ്പോഴും ഓറഞ്ചിലും ചുവപ്പിലും കാണിക്കും)",
        "Route line width" to "റൂട്ട് ലൈനിന്റെ വീതി",
        "How bright the whole night map is (for every theme; also in Light & 3D; kept straight away)" to "രാത്രി മാപ്പ് മുഴുവൻ എത്ര തെളിച്ചമുള്ളതാണ് (എല്ലാ തീമുകൾക്കും; വെളിച്ചവും 3D-യും എന്നതിലും; ഉടനെ നിലനിർത്തും)",
        "Name (optional)" to "പേര് (ഐച്ഛികം)",
        "Give it a name to also keep it under Your themes" to "നിങ്ങളുടെ തീമുകൾ എന്നതിലും സൂക്ഷിക്കാൻ ഒരു പേര് നൽകുക",
        "My theme" to "എന്റെ തീം",
        "Not saved yet: leave without saving and the map goes back as it was" to "ഇതുവരെ സംരക്ഷിച്ചിട്ടില്ല: സംരക്ഷിക്കാതെ പോയാൽ മാപ്പ് പഴയതുപോലെയാകും",
        "Undo changes" to "മാറ്റങ്ങൾ പഴയപടിയാക്കുക",
