        "Map keys" to "മാപ്പ് കീകൾ",
        "Mapbox for the map and routes, TomTom for search" to "മാപ്പിനും റൂട്ടുകൾക്കും Mapbox, തിരയലിന് TomTom",
        "Home and work" to "വീടും ജോലിസ്ഥലവും",
        "One tap to either from the map" to "മാപ്പിൽ നിന്ന് ഏതിലേക്കും ഒറ്റ ടാപ്പ്",
        "Offline pack" to "ഓഫ്‌ലൈൻ പായ്ക്ക്",
        "Routes and search with no signal" to "സിഗ്നൽ ഇല്ലാതെ റൂട്ടുകളും തിരയലും",
        "Your position and the guidance notification" to "നിങ്ങളുടെ സ്ഥാനവും മാർഗ്ഗനിർദ്ദേശ അറിയിപ്പും",
        "Skip setup" to "സജ്ജീകരണം ഒഴിവാക്കുക",
