        "Start driving" to "ഡ്രൈവിംഗ് ആരംഭിക്കുക",
        "Horizon Nav is built for the car: big, clear guidance on Mapbox's 3D map, with live traffic, UK speed limits and cameras, and routes and search that keep working with no signal." to "Horizon Nav കാറിനായി നിർമ്മിച്ചതാണ്: Mapbox-ന്റെ 3D മാപ്പിൽ വലുതും വ്യക്തവുമായ മാർഗ്ഗനിർദ്ദേശം, തത്സമയ ട്രാഫിക്, വേഗപരിധികൾ, ക്യാമറകൾ, സിഗ്നൽ ഇല്ലാതെയും പ്രവർത്തിക്കുന്ന റൂട്ടുകളും തിരയലും.",
        "Live traffic and faster routes as you drive" to "ഡ്രൈവ് ചെയ്യുമ്പോൾ തത്സമയ ട്രാഫിക്കും വേഗമേറിയ റൂട്ടുകളും",
        "Lane guidance, junction signs and speed warnings" to "ലെയ്ൻ മാർഗ്ഗനിർദ്ദേശം, ജംഗ്ഷൻ ബോർഡുകൾ, വേഗ മുന്നറിയിപ്പുകൾ",
        "Offline routes and search for when signal drops" to "സിഗ്നൽ പോകുമ്പോൾ ഓഫ്‌ലൈൻ റൂട്ടുകളും തിരയലും",
        "Everything here can be changed later in Settings." to "ഇവിടെയുള്ളതെല്ലാം പിന്നീട് ക്രമീകരണങ്ങളിൽ മാറ്റാം.",
    )

    private fun p5(): List<Pair<String, String>> = listOf(
        "Horizon Nav uses Mapbox for the map, live traffic, search and routes. It needs your own free Mapbox access token, so the map runs on your Mapbox account (it's free for personal use)." to "മാപ്പ്, തത്സമയ ട്രാഫിക്, തിരയൽ, റൂട്ടുകൾ എന്നിവയ്ക്ക് Horizon Nav Mapbox ഉപയോഗിക്കുന്നു. ഇതിന് നിങ്ങളുടെ സ്വന്തം സൗജന്യ Mapbox ആക്സസ് ടോക്കൺ ആവശ്യമാണ്, അതിനാൽ മാപ്പ് നിങ്ങളുടെ Mapbox അക്കൗണ്ടിൽ പ്രവർത്തിക്കും (വ്യക്തിഗത ഉപയോഗത്തിന് സൗജന്യം).",
        "1. Go to account.mapbox.com and sign up or log in\n2. Open Tokens and copy your Default public token (it starts pk.)\n3. Paste it here" to "1. account.mapbox.com ൽ പോയി സൈൻ അപ്പ് ചെയ്യുക അല്ലെങ്കിൽ ലോഗിൻ ചെയ്യുക\n2. Tokens തുറന്ന് നിങ്ങളുടെ Default public token പകർത്തുക (അത് pk. ൽ ആരംഭിക്കുന്നു)\n3. അത് ഇവിടെ പേസ്റ്റ് ചെയ്യുക",
        "Without a token the map stays blank; routes can still come from the offline pack." to "ടോക്കൺ ഇല്ലെങ്കിൽ മാപ്പ് ശൂന്യമായിരിക്കും; റൂട്ടുകൾ ഇപ്പോഴും ഓഫ്‌ലൈൻ പായ്ക്കിൽ നിന്ന് ലഭിക്കും.",
        "Token added: the map shows as soon as you finish setup" to "ടോക്കൺ ചേർത്തു: സജ്ജീകരണം പൂർത്തിയാക്കിയാലുടൻ മാപ്പ് കാണിക്കും",
        "TomTom key" to "TomTom കീ",
        "Address search uses TomTom, as Horizon Nav always has: it finds house numbers, postcodes and businesses most accurately. TomTom is also the backup for routes and traffic. The key is free." to "Horizon Nav എപ്പോഴും ചെയ്തിരുന്നതുപോലെ വിലാസ തിരയൽ TomTom ഉപയോഗിക്കുന്നു: അത് വീട്ടുനമ്പറുകളും പിൻകോഡുകളും സ്ഥാപനങ്ങളും ഏറ്റവും കൃത്യമായി കണ്ടെത്തുന്നു. റൂട്ടുകൾക്കും ട്രാഫിക്കിനും TomTom ബാക്കപ്പുമാണ്. കീ സൗജന്യമാണ്.",
        "1. Go to developer.tomtom.com and sign up or log in\n2. Open your Dashboard (Keys) and copy your API key\n3. Paste it here" to "1. developer.tomtom.com ൽ പോയി സൈൻ അപ്പ് ചെയ്യുക അല്ലെങ്കിൽ ലോഗിൻ ചെയ്യുക\n2. നിങ്ങളുടെ Dashboard (Keys) തുറന്ന് API കീ പകർത്തുക\n3. അത് ഇവിടെ പേസ്റ്റ് ചെയ്യുക",
        "Without it, search uses Mapbox and OpenStreetMap instead, which miss more house numbers. You can add it later in Settings › Keys & accounts." to "ഇതില്ലെങ്കിൽ, തിരയൽ പകരം Mapbox-ഉം OpenStreetMap-ഉം ഉപയോഗിക്കും, അവ കൂടുതൽ വീട്ടുനമ്പറുകൾ വിട്ടുപോകും. പിന്നീട് ക്രമീകരണങ്ങൾ › കീകളും അക്കൗണ്ടുകളും എന്നതിൽ ചേർക്കാം.",
        "TomTom key added: search uses TomTom" to "TomTom കീ ചേർത്തു: തിരയൽ TomTom ഉപയോഗിക്കുന്നു",
        "Search in" to "ഇവിടെ തിരയുക",
        "Not set · tap to search" to "സജ്ജമാക്കിയിട്ടില്ല · തിരയാൻ ടാപ്പ് ചെയ്യുക",
        "Download the pack once on Wi-Fi and routes, search, speed limits and cameras keep working with no signal. It's a large download (a few GB), so it's best done at home." to "Wi-Fi-ൽ ഒരിക്കൽ പായ്ക്ക് ഡൗൺലോഡ് ചെയ്താൽ റൂട്ടുകളും തിരയലും വേഗപരിധികളും ക്യാമറകളും സിഗ്നൽ ഇല്ലാതെ പ്രവർത്തിക്കും. ഇതൊരു വലിയ ഡൗൺലോഡാണ് (ഏതാനും GB), അതിനാൽ വീട്ടിൽ വച്ച് ചെയ്യുന്നതാണ് നല്ലത്.",
        "Change area" to "പ്രദേശം മാറ്റുക",
        "Offline pack installed" to "ഓഫ്‌ലൈൻ പായ്ക്ക് ഇൻസ്റ്റാൾ ചെയ്തു",
        "Download now" to "ഇപ്പോൾ ഡൗൺലോഡ് ചെയ്യുക",
        "You're not on Wi-Fi" to "നിങ്ങൾ Wi-Fi-ൽ അല്ല",
        " · it carries on if you continue" to " · നിങ്ങൾ തുടർന്നാൽ അത് തുടരും",
        "You can do this later in Settings › Offline maps." to "ഇത് പിന്നീട് ക്രമീകരണങ്ങൾ › ഓഫ്‌ലൈൻ മാപ്പുകൾ എന്നതിൽ ചെയ്യാം.",
        "Allow" to "അനുവദിക്കുക",
        "Needed to show where you are and guide you" to "നിങ്ങൾ എവിടെയാണെന്ന് കാണിക്കാനും വഴികാട്ടാനും ആവശ്യമാണ്",
        "Notifications" to "അറിയിപ്പുകൾ",
        "So guidance keeps going when you switch apps" to "നിങ്ങൾ ആപ്പുകൾ മാറുമ്പോഴും മാർഗ്ഗനിർദ്ദേശം തുടരാൻ",
        "If the Allow button does nothing, the permission was turned down before: allow it in Settings › About & backup › App permissions." to "അനുവദിക്കുക ബട്ടൺ ഒന്നും ചെയ്യുന്നില്ലെങ്കിൽ, അനുമതി മുമ്പ് നിരസിച്ചതാണ്: ക്രമീകരണങ്ങൾ › വിവരവും ബാക്കപ്പും › ആപ്പ് അനുമതികൾ എന്നതിൽ അനുവദിക്കുക.",
        "Mapbox map with no signal" to "സിഗ്നൽ ഇല്ലാതെ Mapbox മാപ്പ്",
        "Mapbox lets each device keep only limited offline areas: a radius round home and several routes fit, a whole country doesn't. Areas you've driven recently are also kept automatically." to "ഓരോ ഉപകരണത്തിനും പരിമിതമായ ഓഫ്‌ലൈൻ പ്രദേശങ്ങൾ മാത്രമേ Mapbox അനുവദിക്കൂ: വീടിന് ചുറ്റുമുള്ള ഒരു പ്രദേശവും ഏതാനും റൂട്ടുകളും ഉൾക്കൊള്ളും, ഒരു രാജ്യം മുഴുവൻ ഉൾക്കൊള്ളില്ല. നിങ്ങൾ അടുത്തിടെ ഓടിച്ച പ്രദേശങ്ങളും സ്വയം സൂക്ഷിക്കും.",
        "Add your Mapbox access token in Settings > Keys & accounts first." to "ആദ്യം ക്രമീകരണങ്ങൾ > കീകളും അക്കൗണ്ടുകളും എന്നതിൽ നിങ്ങളുടെ Mapbox ആക്സസ് ടോക്കൺ ചേർക്കുക.",
        "Around home" to "വീടിന് ചുറ്റും",
        "Set Home first (Search, then save a place as Home)" to "ആദ്യം വീട് സജ്ജമാക്കുക (തിരയുക, എന്നിട്ട് ഒരു സ്ഥലം വീടായി സംരക്ഷിക്കുക)",
        "The 3D map within {0} km of Home · about {1} MB" to "വീടിന് {0} കി.മീ ചുറ്റളവിലെ 3D മാപ്പ് · ഏകദേശം {1} MB",
        "Saving…" to "സംരക്ഷിക്കുന്നു…",
        "Save the map for this route" to "ഈ റൂട്ടിനുള്ള മാപ്പ് സംരക്ഷിക്കുക",
        "Plan a route first" to "ആദ്യം ഒരു റൂട്ട് ആസൂത്രണം ചെയ്യുക",
        " · a strip along the route · about {0} MB" to " · റൂട്ടിലുടനീളം ഒരു ഭാഗം · ഏകദേശം {0} MB",
        "Save every route's map" to "എല്ലാ റൂട്ടിന്റെയും മാപ്പ് സംരക്ഷിക്കുക",
        "When a route starts, its strip is saved in the background" to "ഒരു റൂട്ട് ആരംഭിക്കുമ്പോൾ, അതിന്റെ ഭാഗം പശ്ചാത്തലത്തിൽ സംരക്ഷിക്കും",
        "Save routes" to "റൂട്ടുകൾ സംരക്ഷിക്കുക",
        "On Wi-Fi only" to "Wi-Fi-ൽ മാത്രം",
        "Always (uses mobile data)" to "എപ്പോഴും (മൊബൈൽ ഡാറ്റ ഉപയോഗിക്കും)",
        " · saved" to " · സംരക്ഷിച്ചു",
        " · part saved" to " · ഭാഗികമായി സംരക്ഷിച്ചു",
        "Yes, delete" to "അതെ, ഇല്ലാതാക്കുക",
        "Downloaded areas" to "ഡൗൺലോഡ് ചെയ്ത പ്രദേശങ്ങൾ",
        "Keep as many areas as you like: the one you're in is used automatically (routes work offline within one area). Each is a snapshot of the roads on the day it was built, so update now and then." to "എത്ര പ്രദേശങ്ങൾ വേണമെങ്കിലും സൂക്ഷിക്കാം: നിങ്ങൾ ഉള്ളത് സ്വയം ഉപയോഗിക്കും (ഓഫ്‌ലൈൻ റൂട്ടുകൾ ഒരു പ്രദേശത്തിനുള്ളിൽ പ്രവർത്തിക്കും). ഓരോന്നും അത് നിർമ്മിച്ച ദിവസത്തെ റോഡുകളുടെ ചിത്രമാണ്, അതിനാൽ ഇടയ്ക്കിടെ അപ്ഡേറ്റ് ചെയ്യുക.",
        "Nothing downloaded yet. Pick an area below and download it on Wi-Fi." to "ഇതുവരെ ഒന്നും ഡൗൺലോഡ് ചെയ്തിട്ടില്ല. താഴെ ഒരു പ്രദേശം തിരഞ്ഞെടുത്ത് Wi-Fi-ൽ ഡൗൺലോഡ് ചെയ്യുക.",
        " · in use" to " · ഉപയോഗത്തിൽ",
        " · built {0}" to " · നിർമ്മിച്ചത് {0}",
        " · speed limits and cameras offline" to " · ഓഫ്‌ലൈൻ വേഗപരിധികളും ക്യാമറകളും",
        "Offline speed limits and cameras are now ready for {0}: tap its Update (only the new files download, usually under 100 MB)." to "{0} ന് ഓഫ്‌ലൈൻ വേഗപരിധികളും ക്യാമറകളും ഇപ്പോൾ തയ്യാറാണ്: അതിന്റെ അപ്ഡേറ്റ് ടാപ്പ് ചെയ്യുക (പുതിയ ഫയലുകൾ മാത്രം ഡൗൺലോഡ് ചെയ്യും, സാധാരണയായി 100 MB-യിൽ താഴെ).",
        "The area in use is about {0} months old. Update it on Wi-Fi to pick up new roads and junction changes." to "ഉപയോഗത്തിലുള്ള പ്രദേശത്തിന് ഏകദേശം {0} മാസം പഴക്കമുണ്ട്. പുതിയ റോഡുകളും ജംഗ്ഷൻ മാറ്റങ്ങളും ലഭിക്കാൻ Wi-Fi-ൽ അപ്ഡേറ്റ് ചെയ്യുക.",
        "Add an area" to "ഒരു പ്രദേശം ചേർക്കുക",
        "Area" to "പ്രദേശം",
        "The {0} pack hasn't been built yet, so it can't be downloaded at the moment." to "{0} പായ്ക്ക് ഇതുവരെ നിർമ്മിച്ചിട്ടില്ല, അതിനാൽ ഇപ്പോൾ ഡൗൺലോഡ് ചെയ്യാനാകില്ല.",
        "{0} is already downloaded" to "{0} ഇതിനകം ഡൗൺലോഡ് ചെയ്തിട്ടുണ്ട്",
        "Download {0}" to "{0} ഡൗൺലോഡ് ചെയ്യുക",
        "Best done on Wi-Fi: a country is usually 1 to 4 GB" to "Wi-Fi-ൽ ചെയ്യുന്നതാണ് നല്ലത്: ഒരു രാജ്യം സാധാരണയായി 1 മുതൽ 4 GB വരെയാണ്",
        " · you can leave this page" to " · നിങ്ങൾക്ക് ഈ പേജ് വിടാം",
        "Without signal" to "സിഗ്നൽ ഇല്ലാതെ",
        "Which map to draw" to "ഉപയോഗിക്കേണ്ട മാപ്പ്",
        "Downloaded" to "ഡൗൺലോഡ് ചെയ്തത്",
        "Online" to "ഓൺലൈൻ",
        "Auto: with no signal Mapbox's map carries on with the areas it has stored (where you've been recently, and saved Mapbox areas); the downloaded pack's map takes over only where Mapbox has nothing, and the online map comes back with signal" to "ഓട്ടോ: സിഗ്നൽ ഇല്ലാത്തപ്പോൾ Mapbox-ന്റെ മാപ്പ് അത് സൂക്ഷിച്ച പ്രദേശങ്ങളുമായി തുടരും (നിങ്ങൾ അടുത്തിടെ പോയ ഇടങ്ങൾ, സംരക്ഷിച്ച Mapbox പ്രദേശങ്ങൾ); Mapbox-ന് ഒന്നുമില്ലാത്തിടത്ത് മാത്രം ഡൗൺലോഡ് ചെയ്ത പായ്ക്കിന്റെ മാപ്പ് ഏറ്റെടുക്കും, സിഗ്നൽ വരുമ്പോൾ ഓൺലൈൻ മാപ്പ് തിരികെ വരും",
        "Choose an area" to "ഒരു പ്രദേശം തിരഞ്ഞെടുക്കുക",
        "Search, e.g. France, Texas, Bavaria" to "തിരയുക, ഉദാ. France, Texas, Bavaria",
        "NEAR YOU" to "നിങ്ങളുടെ സമീപം",
        "or all of {0}" to "അല്ലെങ്കിൽ {0} മുഴുവനും",
        "{0} regions ›" to "{0} പ്രദേശങ്ങൾ ›",
        "Whole country" to "രാജ്യം മുഴുവൻ",
        "No area matches. Try the country's name in English." to "പൊരുത്തപ്പെടുന്ന പ്രദേശമില്ല. രാജ്യത്തിന്റെ പേര് ഇംഗ്ലീഷിൽ ശ്രമിക്കുക.",
        "There's no web browser on this unit. Scan the code with your phone instead." to "ഈ യൂണിറ്റിൽ വെബ് ബ്രൗസർ ഇല്ല. പകരം നിങ്ങളുടെ ഫോൺ ഉപയോഗിച്ച് കോഡ് സ്കാൻ ചെയ്യുക.",
        "Enjoying Horizon Nav?" to "Horizon Nav ഇഷ്ടമായോ?",
        "It's free, with no ads, made by one person in their spare time. If it's useful to you, a small donation helps keep it going." to "ഇത് സൗജന്യമാണ്, പരസ്യങ്ങളില്ല, ഒരാൾ ഒഴിവുസമയത്ത് നിർമ്മിച്ചത്. ഇത് നിങ്ങൾക്ക് ഉപകാരപ്രദമാണെങ്കിൽ, ചെറിയൊരു സംഭാവന ഇത് മുന്നോട്ട് കൊണ്ടുപോകാൻ സഹായിക്കും.",
        "QR code for the PayPal donation page" to "PayPal സംഭാവന പേജിനുള്ള QR കോഡ്",
        "Scan with your phone" to "നിങ്ങളുടെ ഫോൺ ഉപയോഗിച്ച് സ്കാൻ ചെയ്യുക",
        "Opens PayPal on your phone" to "നിങ്ങളുടെ ഫോണിൽ PayPal തുറക്കുന്നു",
        "Donate on this screen" to "ഈ സ്ക്രീനിൽ സംഭാവന നൽകുക",
        "Maybe later" to "പിന്നീട് ആകാം",
        "This version is installed and ready. The details of what changed aren't available right now." to "ഈ പതിപ്പ് ഇൻസ്റ്റാൾ ചെയ്ത് തയ്യാറാണ്. എന്താണ് മാറിയതെന്നതിന്റെ വിശദാംശങ്ങൾ ഇപ്പോൾ ലഭ്യമല്ല.",
        "3D" to "3D",
        "Clear the report" to "റിപ്പോർട്ട് മായ്ക്കുക",
        "Delete the pack" to "പായ്ക്ക് ഇല്ലാതാക്കുക",
        "Storage" to "സ്റ്റോറേജ്",
        "Speedometer and speed-limit sign" to "സ്പീഡോമീറ്ററും വേഗപരിധി ബോർഡും",
        "MAP" to "മാപ്പ്",
        "DRIVING" to "ഡ്രൈവിംഗ്",
        "YOU" to "നിങ്ങൾ",
        "DEVICE" to "ഉപകരണം",
        "Search for your work address or postcode" to "നിങ്ങളുടെ ജോലിസ്ഥല വിലാസമോ പിൻകോഡോ തിരയുക",
        "Search for your home address or postcode" to "നിങ്ങളുടെ വീട്ടുവിലാസമോ പിൻകോഡോ തിരയുക",
        "Going home" to "വീട്ടിലേക്ക് പോകുന്നു",
        "Home isn't set yet" to "വീട് ഇതുവരെ സജ്ജമാക്കിയിട്ടില്ല",
        "Going to work" to "ജോലിസ്ഥലത്തേക്ക് പോകുന്നു",
        "Work isn't set yet" to "ജോലിസ്ഥലം ഇതുവരെ സജ്ജമാക്കിയിട്ടില്ല",
        "Looking for {0} along your route" to "നിങ്ങളുടെ റൂട്ടിൽ {0} തിരയുന്നു",
        "Looking for {0} nearby" to "സമീപത്ത് {0} തിരയുന്നു",
        "Avoiding toll roads" to "ടോൾ റോഡുകൾ ഒഴിവാക്കുന്നു",
        "Avoiding motorways" to "മോട്ടോർവേകൾ ഒഴിവാക്കുന്നു",
        "Looking for a way round" to "മറ്റൊരു വഴി തിരയുന്നു",
        "There's no route to change" to "മാറ്റാൻ റൂട്ടൊന്നുമില്ല",
        "There's no route at the moment" to "ഇപ്പോൾ റൂട്ടൊന്നുമില്ല",
        "You'll arrive at {0}, in {1}. {2} to go." to "നിങ്ങൾ {1} കഴിഞ്ഞ് {0} ന് എത്തും. ഇനി {2}.",
        " {0} minutes of traffic." to " {0} മിനിറ്റ് ട്രാഫിക്.",
        "Voice guidance on" to "ശബ്ദ മാർഗ്ഗനിർദ്ദേശം ഓൺ",
        "Voice off" to "ശബ്ദം ഓഫ്",
        "Route ended" to "റൂട്ട് അവസാനിച്ചു",
        "It's {0}" to "സമയം {0}",
        "{0} ahead, {1} {2}" to "മുന്നിൽ {0}, {1} {2}",
        "Low bridge" to "താഴ്ന്ന പാലം",
