        "Your saved places are in the row of tiles under the search bar, which ends with Add a place" to "നിങ്ങൾ സംരക്ഷിച്ച സ്ഥലങ്ങൾ തിരയൽ ബാറിന് താഴെയുള്ള ടൈലുകളുടെ നിരയിലാണ്, അത് ഒരു സ്ഥലം ചേർക്കുക എന്നതിൽ അവസാനിക്കുന്നു",
        "Places you drive to show up here" to "നിങ്ങൾ ഡ്രൈവ് ചെയ്യുന്ന സ്ഥലങ്ങൾ ഇവിടെ കാണിക്കും",
        "Save somewhere" to "എവിടെയെങ്കിലും സംരക്ഷിക്കുക",
        "Add a stop" to "ഒരു സ്റ്റോപ്പ് ചേർക്കുക",
        "Couldn't find {0}" to "{0} കണ്ടെത്താനായില്ല",
        "No stops yet. Add one and the route goes through it on the way." to "ഇതുവരെ സ്റ്റോപ്പുകളൊന്നുമില്ല. ഒന്ന് ചേർത്താൽ റൂട്ട് വഴിയിൽ അതിലൂടെ പോകും.",
        "Search for a place on the way" to "വഴിയിൽ ഒരു സ്ഥലം തിരയുക",
        "Your tracks" to "നിങ്ങളുടെ ട്രാക്കുകൾ",
        "No saved places yet." to "ഇതുവരെ സംരക്ഷിച്ച സ്ഥലങ്ങളില്ല.",
        "Map lettering" to "മാപ്പിലെ അക്ഷരങ്ങൾ",
        "Font" to "ഫോണ്ട്",
        "The lettering for road and place names on the map" to "മാപ്പിലെ റോഡുകളുടെയും സ്ഥലങ്ങളുടെയും പേരുകൾക്കുള്ള അക്ഷരങ്ങൾ",
        "Mapbox answers and your token works, but the map isn't drawing on this device. Please send a report from Settings › Feedback so it can be looked into." to "Mapbox മറുപടി നൽകുന്നു, നിങ്ങളുടെ ടോക്കൺ പ്രവർത്തിക്കുന്നു, പക്ഷേ ഈ ഉപകരണത്തിൽ മാപ്പ് വരയ്ക്കുന്നില്ല. ഇത് പരിശോധിക്കാൻ ക്രമീകരണങ്ങൾ › ഫീഡ്ബാക്ക് എന്നതിൽ നിന്ന് ഒരു റിപ്പോർട്ട് അയയ്ക്കുക.",
        "Mapbox's server answered with an error. Try again later." to "Mapbox-ന്റെ സെർവർ ഒരു പിശകോടെ മറുപടി നൽകി. പിന്നീട് വീണ്ടും ശ്രമിക്കുക.",
        "This device can't find Mapbox's server. A private DNS or ad blocker may be blocking api.mapbox.com: allow it, or turn off Private DNS in Android's network settings." to "ഈ ഉപകരണത്തിന് Mapbox-ന്റെ സെർവർ കണ്ടെത്താനാകുന്നില്ല. ഒരു പ്രൈവറ്റ് DNS അല്ലെങ്കിൽ ആഡ് ബ്ലോക്കർ api.mapbox.com തടയുന്നുണ്ടാകാം: അത് അനുവദിക്കുക, അല്ലെങ്കിൽ Android-ന്റെ നെറ്റ്‌വർക്ക് ക്രമീകരണങ്ങളിൽ പ്രൈവറ്റ് DNS ഓഫാക്കുക.",
        "Mapbox's server isn't answering from this device. Check the internet connection: a Wi‑Fi that needs signing in, or a firewall, can block it." to "ഈ ഉപകരണത്തിൽ നിന്ന് Mapbox-ന്റെ സെർവർ മറുപടി നൽകുന്നില്ല. ഇന്റർനെറ്റ് കണക്ഷൻ പരിശോധിക്കുക: സൈൻ ഇൻ ആവശ്യമുള്ള Wi‑Fi, അല്ലെങ്കിൽ ഫയർവാൾ, അത് തടഞ്ഞേക്കാം.",
        "Showing traffic while you’re stopped" to "നിങ്ങൾ നിർത്തിയിരിക്കുമ്പോൾ ട്രാഫിക് കാണിക്കുന്നു",
        "Help test Horizon Maps on Google Play" to "Google Play-ൽ Horizon Maps പരീക്ഷിക്കാൻ സഹായിക്കുക",
        "Horizon Nav is coming to the Play Store as Horizon Maps, and Google needs at least 12 testers for 14 days first. It's the same app, installed separately, so it won't touch this one. Keep it installed for 14 days and use it now and then." to "Horizon Nav, Horizon Maps എന്ന പേരിൽ Play Store-ലേക്ക് വരുന്നു, അതിന് മുമ്പ് Google-ന് 14 ദിവസത്തേക്ക് കുറഞ്ഞത് 12 ടെസ്റ്റർമാരെ വേണം. ഇത് ഇതേ ആപ്പാണ്, പ്രത്യേകം ഇൻസ്റ്റാൾ ചെയ്യുന്നത്, അതിനാൽ ഇതിനെ ബാധിക്കില്ല. 14 ദിവസം ഇൻസ്റ്റാൾ ചെയ്ത് നിലനിർത്തി ഇടയ്ക്കിടെ ഉപയോഗിക്കുക.",
        "Join the testers group" to "ടെസ്റ്റർമാരുടെ ഗ്രൂപ്പിൽ ചേരുക",
        "Install Horizon Maps from the Play Store" to "Play Store-ൽ നിന്ന് Horizon Maps ഇൻസ്റ്റാൾ ചെയ്യുക",
        "Sign in with the Google account you use for the Play Store." to "Play Store-ന് ഉപയോഗിക്കുന്ന Google അക്കൗണ്ട് ഉപയോഗിച്ച് സൈൻ ഇൻ ചെയ്യുക.",
        "QR code for the testers group" to "ടെസ്റ്റർമാരുടെ ഗ്രൂപ്പിനുള്ള QR കോഡ്",
        "Join the group" to "ഗ്രൂപ്പിൽ ചേരുക",
        "Install from Play" to "Play-ൽ നിന്ന് ഇൻസ്റ്റാൾ ചെയ്യുക",
        "This opens once Google has approved the test. Join the group now and you'll be ready." to "Google ടെസ്റ്റ് അംഗീകരിച്ചുകഴിഞ്ഞാൽ ഇത് തുറക്കും. ഇപ്പോൾ ഗ്രൂപ്പിൽ ചേർന്നാൽ നിങ്ങൾ തയ്യാറായിരിക്കും.",
        "Don't show again" to "വീണ്ടും കാണിക്കരുത്",
        "COMING SOON" to "ഉടൻ വരുന്നു",
        "Horizon Maps is coming to Google Play" to "Horizon Maps Google Play-ലേക്ക് വരുന്നു",
        "Tap to help test it" to "ഇത് പരീക്ഷിക്കാൻ സഹായിക്കാൻ ടാപ്പ് ചെയ്യുക",
        "Update available" to "അപ്ഡേറ്റ് ലഭ്യമാണ്",
        "What's in it" to "ഇതിൽ എന്തുണ്ട്",
        "Your settings and places are kept" to "നിങ്ങളുടെ ക്രമീകരണങ്ങളും സ്ഥലങ്ങളും നിലനിൽക്കും",
        "and {0} more" to "കൂടാതെ {0} എണ്ണം കൂടി",
        "New" to "പുതിയത്",
        "Improved" to "മെച്ചപ്പെടുത്തിയത്",
        "Fixed" to "പരിഹരിച്ചത്",
        "Close Horizon Nav" to "Horizon Nav അടയ്ക്കുക",
        "Ends the route and stops GPS" to "റൂട്ട് അവസാനിപ്പിച്ച് GPS നിർത്തുന്നു",
        "Your places next to Home and Work" to "നിങ്ങളുടെ സ്ഥലങ്ങൾ ബട്ടൺ",
        "Only the starred ones show there" to "നക്ഷത്രമിട്ടവ മാത്രം അവിടെ കാണിക്കും",
        "Shown next to Home and Work" to "വീടിനും ജോലിസ്ഥലത്തിനും അടുത്ത് കാണിക്കുന്നു",
        "Not shown next to Home and Work" to "വീടിനും ജോലിസ്ഥലത്തിനും അടുത്ത് കാണിക്കുന്നില്ല",
        "The starred ones show next to Home and Work under the search bar; tap a star to change it. All of them are in search and the Your places shortcut." to "നക്ഷത്രമിട്ടവ തിരയൽ ബാറിന് താഴെ വീടിനും ജോലിസ്ഥലത്തിനും അടുത്ത് കാണിക്കും; മാറ്റാൻ ഒരു നക്ഷത്രത്തിൽ ടാപ്പ് ചെയ്യുക. എല്ലാം തിരയലിലും നിങ്ങളുടെ സ്ഥലങ്ങൾ കുറുക്കുവഴിയിലുമുണ്ട്.",
        "Road name, arrow, tunnels, media, locking" to "റോഡിന്റെ പേര്, ആരോ, തുരങ്കങ്ങൾ, മീഡിയ, ലോക്കിംഗ്",
        "Light, weather & 3D" to "വെളിച്ചം, കാലാവസ്ഥ, 3D",
        "Light, rain and snow, radar, 3D, sky" to "വെളിച്ചം, മഴയും മഞ്ഞും, റഡാർ, 3D, ആകാശം",
        "Traffic, lights, cameras, signs, lamps" to "ട്രാഫിക്, ലൈറ്റുകൾ, ക്യാമറകൾ, ബോർഡുകൾ, വിളക്കുകൾ",
        "Brightness, sizes, speed, card positions, units" to "തെളിച്ചം, വലുപ്പങ്ങൾ, വേഗം, കാർഡുകളുടെ സ്ഥാനങ്ങൾ, യൂണിറ്റുകൾ",
        "Colours and lettering" to "നിറങ്ങളും അക്ഷരങ്ങളും",
        "Avoid car trains" to "കാർ ട്രെയിനുകൾ ഒഴിവാക്കുക",
        "Trains that carry your car, like the Channel Tunnel shuttle or the Alpine tunnel trains" to "ചാനൽ ടണൽ ഷട്ടിൽ അല്ലെങ്കിൽ ആൽപ്സ് തുരങ്ക ട്രെയിനുകൾ പോലെ നിങ്ങളുടെ കാർ കൊണ്ടുപോകുന്ന ട്രെയിനുകൾ",
        "Light and shadows come from where the sun really is right now, and at night from the moon" to "വെളിച്ചവും നിഴലുകളും ഇപ്പോൾ സൂര്യൻ യഥാർത്ഥത്തിൽ എവിടെയാണോ അവിടെ നിന്ന്, രാത്രിയിൽ ചന്ദ്രനിൽ നിന്ന്",
        "Navigate" to "നാവിഗേറ്റ് ചെയ്യുക",
        "Phone's dark mode" to "ഫോണിന്റെ ഡാർക്ക് മോഡ്",
        "Auto switches at sunrise and sunset, with dawn and dusk light in between. Phone's dark mode follows your phone's own light / dark setting. My times switches at the times you set" to "ഓട്ടോ സൂര്യോദയത്തിലും സൂര്യാസ്തമയത്തിലും മാറുന്നു, ഇടയിൽ പ്രഭാതത്തിന്റെയും സന്ധ്യയുടെയും വെളിച്ചം. ഫോണിന്റെ ഡാർക്ക് മോഡ് നിങ്ങളുടെ ഫോണിന്റെ സ്വന്തം ലൈറ്റ് / ഡാർക്ക് ക്രമീകരണം പിന്തുടരുന്നു. എന്റെ സമയങ്ങൾ നിങ്ങൾ സജ്ജമാക്കുന്ന സമയങ്ങളിൽ മാറുന്നു",
        "Clock on the map" to "മാപ്പിൽ ക്ലോക്ക്",
        "The time, with the speedometer. Handy when the head unit's status bar is covered" to "സ്പീഡോമീറ്ററിനൊപ്പം സമയം. ഹെഡ് യൂണിറ്റിന്റെ സ്റ്റാറ്റസ് ബാർ മറഞ്ഞിരിക്കുമ്പോൾ ഉപകാരപ്രദം",
        "Includes settings, saved places and GPX tracks, not the offline pack. Your API keys are only included with the switch on. A backup from Horizon Launcher can be restored here too." to "ക്രമീകരണങ്ങളും സംരക്ഷിച്ച സ്ഥലങ്ങളും GPX ട്രാക്കുകളും ഉൾപ്പെടുന്നു, ഓഫ്‌ലൈൻ പായ്ക്ക് അല്ല. സ്വിച്ച് ഓണാണെങ്കിൽ മാത്രമേ നിങ്ങളുടെ API കീകൾ ഉൾപ്പെടുത്തൂ. Horizon Launcher-ൽ നിന്നുള്ള ബാക്കപ്പും ഇവിടെ പുനഃസ്ഥാപിക്കാം.",
        "Settings, places and tracks" to "ക്രമീകരണങ്ങൾ, സ്ഥലങ്ങൾ, ട്രാക്കുകൾ",
        "{0} GPX tracks" to "{0} GPX ട്രാക്കുകൾ",
        "Automatic backup" to "ഓട്ടോമാറ്റിക് ബാക്കപ്പ്",
        "Once a day, to a folder you choose" to "ദിവസത്തിലൊരിക്കൽ, നിങ്ങൾ തിരഞ്ഞെടുക്കുന്ന ഫോൾഡറിലേക്ക്",
        "Once a day, to {0}" to "ദിവസത്തിലൊരിക്കൽ, {0} ലേക്ക്",
        "the last one couldn't be saved: choose the folder again" to "അവസാനത്തേത് സംരക്ഷിക്കാനായില്ല: ഫോൾഡർ വീണ്ടും തിരഞ്ഞെടുക്കുക",
        "last {0}" to "അവസാനം {0}",
        "Choose folder" to "ഫോൾഡർ തിരഞ്ഞെടുക്കുക",
        "This unit can't pick a folder" to "ഈ യൂണിറ്റിന് ഫോൾഡർ തിരഞ്ഞെടുക്കാനാകില്ല",
        "Turn off" to "ഓഫാക്കുക",
        "Backup files" to "ബാക്കപ്പ് ഫയലുകൾ",
        "Replace the last one" to "അവസാനത്തേത് മാറ്റിസ്ഥാപിക്കുക",
        "Keep the last 7" to "അവസാനത്തെ 7 എണ്ണം സൂക്ഷിക്കുക",
        "Replace the last one keeps a single file, overwritten each day. Keep the last 7 adds one a day and removes the oldest" to "അവസാനത്തേത് മാറ്റിസ്ഥാപിക്കുക എന്നത് ദിവസവും മാറ്റിയെഴുതുന്ന ഒരൊറ്റ ഫയൽ സൂക്ഷിക്കും. അവസാനത്തെ 7 എണ്ണം സൂക്ഷിക്കുക ദിവസവും ഒന്ന് ചേർത്ത് ഏറ്റവും പഴയത് നീക്കം ചെയ്യും",
        "Back up or restore your settings, saved places and GPX tracks" to "നിങ്ങളുടെ ക്രമീകരണങ്ങൾ, സംരക്ഷിച്ച സ്ഥലങ്ങൾ, GPX ട്രാക്കുകൾ എന്നിവ ബാക്കപ്പ് ചെയ്യുക അല്ലെങ്കിൽ പുനഃസ്ഥാപിക്കുക",
        "LPG (Autogas)" to "LPG (ഓട്ടോഗ്യാസ്)",
        "Italy works by itself too, with the government's prices from each morning, updated once a day." to "ഇറ്റലിയും സ്വയം പ്രവർത്തിക്കും, എല്ലാ രാവിലെയുമുള്ള സർക്കാർ വിലകളോടെ, ദിവസത്തിലൊരിക്കൽ അപ്ഡേറ്റ് ചെയ്യും.",
        "Mapbox is turning down satellite pictures for your token (too many requests). If it keeps happening, check the token is your own: one copied from someone else is shared by everyone using it. A free one is at account.mapbox.com" to "Mapbox നിങ്ങളുടെ ടോക്കണിന് സാറ്റലൈറ്റ് ചിത്രങ്ങൾ നിരസിക്കുന്നു (വളരെയധികം അഭ്യർത്ഥനകൾ). ഇത് തുടർന്നാൽ, ടോക്കൺ നിങ്ങളുടേതാണോ എന്ന് പരിശോധിക്കുക: മറ്റൊരാളിൽ നിന്ന് പകർത്തിയത് അത് ഉപയോഗിക്കുന്ന എല്ലാവരും പങ്കിടുന്നു. സൗജന്യമായി ഒന്ന് account.mapbox.com ൽ ലഭിക്കും",
        "The map couldn't load your 3D model, so the car shows instead. Try exporting it again as a plain .glb (no Draco or KTX2 compression)" to "മാപ്പിന് നിങ്ങളുടെ 3D മോഡൽ ലോഡ് ചെയ്യാനായില്ല, അതിനാൽ പകരം കാർ കാണിക്കുന്നു. സാധാരണ .glb ആയി (Draco അല്ലെങ്കിൽ KTX2 കംപ്രഷൻ ഇല്ലാതെ) വീണ്ടും എക്സ്പോർട്ട് ചെയ്തു നോക്കുക",
        "Mapbox's servers are turning down satellite pictures right now (too many requests). It's on Mapbox's side, not your token or the app: satellite should come back by itself, so try again later" to "Mapbox-ന്റെ സെർവറുകൾ ഇപ്പോൾ സാറ്റലൈറ്റ് ചിത്രങ്ങൾ നിരസിക്കുന്നു (വളരെയധികം അഭ്യർത്ഥനകൾ). ഇത് Mapbox-ന്റെ ഭാഗത്താണ്, നിങ്ങളുടെ ടോക്കണിലോ ആപ്പിലോ അല്ല: സാറ്റലൈറ്റ് സ്വയം തിരികെ വരും, പിന്നീട് വീണ്ടും ശ്രമിക്കുക",
        "Satellite view" to "സാറ്റലൈറ്റ് കാഴ്ച",
        "Live traffic and delays" to "തത്സമയ ട്രാഫിക്കും താമസങ്ങളും",
        "Routes round the traffic" to "ട്രാഫിക് ചുറ്റിപ്പോകുന്ന റൂട്ടുകൾ",
        "Lanes and junction signs" to "ലെയ്നുകളും ജംഗ്ഷൻ ബോർഡുകളും",
        "basic" to "അടിസ്ഥാനം",
        "Address and place search" to "വിലാസവും സ്ഥലവും തിരയൽ",
        "Speed cameras and limits" to "സ്പീഡ് ക്യാമറകളും പരിധികളും",
        "Free" to "സൗജന്യം",
        "Plus is on. Thank you for supporting Horizon Maps!" to "Plus ഓണാണ്. Horizon Maps-നെ പിന്തുണച്ചതിന് നന്ദി!",
        "Manage in Google Play" to "Google Play-ൽ നിയന്ത്രിക്കുക",
        "Getting prices from Google Play…" to "Google Play-ൽ നിന്ന് വിലകൾ ലഭ്യമാക്കുന്നു…",
        "a year · save 20%" to "ഒരു വർഷം · 20% ലാഭിക്കാം",
        "a month" to "ഒരു മാസം",
        "Start {0}-day free trial" to "{0} ദിവസത്തെ സൗജന്യ ട്രയൽ ആരംഭിക്കുക",
        "Subscribe" to "സബ്സ്ക്രൈബ് ചെയ്യുക",
        "Cancel any time in Google Play. Without Plus, Horizon Maps keeps working on OpenStreetMap." to "Google Play-ൽ എപ്പോൾ വേണമെങ്കിലും റദ്ദാക്കാം. Plus ഇല്ലാതെ Horizon Maps OpenStreetMap-ൽ പ്രവർത്തിക്കും.",
        "from {0} a month" to "മാസത്തിന് {0} മുതൽ",
        "3D map and satellite, live traffic, smarter routes and full search." to "3D മാപ്പും സാറ്റലൈറ്റും, തത്സമയ ട്രാഫിക്, മികച്ച റൂട്ടുകൾ, പൂർണ്ണ തിരയൽ.",
        "OpenStreetMap map, search and routes (from a downloaded country pack). No traffic. Upgrade any time." to "OpenStreetMap മാപ്പ്, തിരയൽ, റൂട്ടുകൾ (ഡൗൺലോഡ് ചെയ്ത രാജ്യ പായ്ക്കിൽ നിന്ന്). ട്രാഫിക് ഇല്ല. എപ്പോൾ വേണമെങ്കിലും അപ്ഗ്രേഡ് ചെയ്യാം.",
        "Horizon Maps Plus is on" to "Horizon Maps Plus ഓണാണ്",
        "Get Horizon Maps Plus" to "Horizon Maps Plus നേടുക",
        "Thanks for subscribing · tap to manage" to "സബ്സ്ക്രൈബ് ചെയ്തതിന് നന്ദി · നിയന്ത്രിക്കാൻ ടാപ്പ് ചെയ്യുക",
        "3D map, satellite, live traffic and smarter routes" to "3D മാപ്പ്, സാറ്റലൈറ്റ്, തത്സമയ ട്രാഫിക്, മികച്ച റൂട്ടുകൾ",
        "How you'd like to navigate" to "നിങ്ങൾ എങ്ങനെ നാവിഗേറ്റ് ചെയ്യാൻ ആഗ്രഹിക്കുന്നു",
        "Horizon Maps Plus or the free version" to "Horizon Maps Plus അല്ലെങ്കിൽ സൗജന്യ പതിപ്പ്",
        "Plus is on: everything's ready, with no keys to set up." to "Plus ഓണാണ്: എല്ലാം തയ്യാറാണ്, കീകളൊന്നും സജ്ജമാക്കേണ്ടതില്ല.",
        "With the free version, download your country in the Offline pack step: it's what plans your routes." to "സൗജന്യ പതിപ്പിൽ, ഓഫ്‌ലൈൻ പായ്ക്ക് ഘട്ടത്തിൽ നിങ്ങളുടെ രാജ്യം ഡൗൺലോഡ് ചെയ്യുക: അതാണ് നിങ്ങളുടെ റൂട്ടുകൾ ആസൂത്രണം ചെയ്യുന്നത്.",
        "Plus is on: the map, search, routes and traffic use Horizon Maps' own accounts, so there are no keys to add." to "Plus ഓണാണ്: മാപ്പും തിരയലും റൂട്ടുകളും ട്രാഫിക്കും Horizon Maps-ന്റെ സ്വന്തം അക്കൗണ്ടുകൾ ഉപയോഗിക്കുന്നു, അതിനാൽ കീകൾ ചേർക്കേണ്ടതില്ല.",
        "Weak signal: the route service couldn't be reached. Trying again by itself…" to "സിഗ്നൽ കുറവാണ്: റൂട്ട് സേവനത്തിലേക്ക് എത്താനായില്ല. സ്വയം വീണ്ടും ശ്രമിക്കുന്നു…",
        "Imported {0} into Your places, in the Google Maps group · already saved {1}" to "{0} എണ്ണം നിങ്ങളുടെ സ്ഥലങ്ങളിലേക്ക് Google Maps ഗ്രൂപ്പിൽ ഇമ്പോർട് ചെയ്തു · മുമ്പേ സേവ് ചെയ്തവ {1}",
        "Choose a Saved Places.json file from Google Takeout. The places go in a Google Maps group here" to "Google Takeout-ൽ നിന്നുള്ള Saved Places.json ഫയൽ തിരഞ്ഞെടുക്കുക. സ്ഥലങ്ങൾ ഇവിടെ Google Maps ഗ്രൂപ്പിലേക്ക് പോകും",
        "Move to Your places" to "നിങ്ങളുടെ സ്ഥലങ്ങളിലേക്ക് മാറ്റുക",
        "{0} moved to Your places" to "{0} നിങ്ങളുടെ സ്ഥലങ്ങളിലേക്ക് മാറ്റി",
        "Move every favourite to Your places" to "എല്ലാ പ്രിയപ്പെട്ടവയും നിങ്ങളുടെ സ്ഥലങ്ങളിലേക്ക് മാറ്റുക",
        "In a Favourites group there, so they leave the row next to Home and Work" to "അവിടെ പ്രിയപ്പെട്ടവ ഗ്രൂപ്പിൽ, അതിനാൽ വീട്, ജോലിസ്ഥലം എന്നിവയുടെ അടുത്തുള്ള നിരയിൽ നിന്ന് മാറും",
        "Move all" to "എല്ലാം മാറ്റുക",
        "Use where I am now" to "ഞാൻ ഇപ്പോഴുള്ള സ്ഥലം ഉപയോഗിക്കുക",
        "Your location" to "നിങ്ങളുടെ ലൊക്കേഷൻ",
        "or" to "അല്ലെങ്കിൽ",
        "End camera" to "അവസാന ക്യാമറ",
        "That spot isn't on a road open to cars: the route goes to the nearest public road, {0} away" to "ആ സ്ഥലം കാറുകൾക്ക് പോകാവുന്ന റോഡിലല്ല: റൂട്ട് {0} അകലെയുള്ള ഏറ്റവും അടുത്ത പൊതു റോഡിലേക്ക് പോകും",
        "Saved places on the map" to "മാപ്പിൽ സേവ് ചെയ്ത സ്ഥലങ്ങൾ",
        "Home, Work, favourites and starred places. Tap one to go there" to "വീട്, ജോലിസ്ഥലം, പ്രിയപ്പെട്ടവ, നക്ഷത്രമിട്ട സ്ഥലങ്ങൾ. അവിടേക്ക് പോകാൻ ടാപ്പ് ചെയ്യുക",
        "Saved places icons" to "സേവ് ചെയ്ത സ്ഥലങ്ങളുടെ ഐക്കണുകൾ",
        "Upcoming speed limits" to "വരാനിരിക്കുന്ന വേഗപരിധികൾ",
        "The next limit on your route, as a sign on the map where it changes and a small one by your limit sign with how far it is, from about half a mile away" to "റൂട്ടിലെ അടുത്ത പരിധി, മാറുന്നിടത്ത് മാപ്പിലെ ബോർഡായും നിങ്ങളുടെ ബോർഡിനടുത്ത് ദൂരത്തോടെ ചെറുതായും, ഏകദേശം 800 മീ മുമ്പേ",
        "The free version uses OpenStreetMap, with routes from your downloaded country pack. Horizon Maps Plus adds detailed 3D buildings and landmarks, satellite and live traffic, with no keys to set up." to "സൗജന്യ പതിപ്പ് OpenStreetMap ഉപയോഗിക്കുന്നു, നിങ്ങൾ ഡൗൺലോഡ് ചെയ്ത രാജ്യ പായ്ക്കിൽ നിന്നുള്ള റൂട്ടുകളോടെ. Horizon Maps Plus വിശദമായ 3D കെട്ടിടങ്ങളും അടയാള സ്ഥലങ്ങളും സാറ്റലൈറ്റും തത്സമയ ട്രാഫിക്കും ചേർക്കുന്നു, കീകളൊന്നും സജ്ജമാക്കാതെ.",
        "In rain or snow" to "മഴയിലോ മഞ്ഞിലോ",
        "A greyer, softer daylight when it's raining or snowing where you are" to "നിങ്ങൾ ഉള്ളിടത്ത് മഴയോ മഞ്ഞോ പെയ്യുമ്പോൾ കൂടുതൽ ചാരനിറമുള്ള, മൃദുവായ പകൽവെളിച്ചം",
        "A pale wash over the map and a thick haze in fog or mist. Off shows those as a plain overcast day" to "മൂടൽമഞ്ഞിൽ മാപ്പിന് മുകളിൽ മങ്ങിയ ആവരണവും കട്ടിയുള്ള മൂടലും. ഓഫ് ആണെങ്കിൽ സാധാരണ മേഘാവൃത ദിവസമായി കാണിക്കും",
        "Checks the weather where you are every 10 minutes, for everything below" to "നിങ്ങൾ ഉള്ളിടത്തെ കാലാവസ്ഥ ഓരോ 10 മിനിറ്റിലും പരിശോധിക്കുന്നു, താഴെയുള്ള എല്ലാത്തിനും",
        "Fetches the weather where you are now" to "നിങ്ങൾ ഇപ്പോൾ ഉള്ളിടത്തെ കാലാവസ്ഥ എടുക്കുന്നു",
        "Fog and mist on the map" to "മാപ്പിൽ മൂടൽമഞ്ഞ്",
        "Forecasts and radar" to "പ്രവചനങ്ങളും റഡാറും",
        "Haze towards the horizon" to "ചക്രവാളത്തിലേക്ക് മൂടൽ",
        "Light, shadows, 3D, sky, satellite" to "വെളിച്ചം, നിഴലുകൾ, 3D, ആകാശം, സാറ്റലൈറ്റ്",
        "Live weather" to "തത്സമയ കാലാവസ്ഥ",
        "Live weather (Settings > Weather) comes from Open-Meteo. In the UK, a free Met Office key is usually more accurate: datahub.metoffice.gov.uk, subscribe to Site-Specific Forecast (Global spot), then paste the API key. If the Met Office fails, Open-Meteo is used." to "തത്സമയ കാലാവസ്ഥ (ക്രമീകരണങ്ങൾ > കാലാവസ്ഥ) Open-Meteo-ൽ നിന്നാണ്. UK-ൽ സൗജന്യ Met Office കീ സാധാരണയായി കൂടുതൽ കൃത്യമാണ്: datahub.metoffice.gov.uk ൽ Site-Specific Forecast (Global spot) സബ്സ്ക്രൈബ് ചെയ്ത്, API കീ പേസ്റ്റ് ചെയ്യുക. Met Office പരാജയപ്പെട്ടാൽ Open-Meteo ഉപയോഗിക്കും.",
        "Live weather, rain, snow, fog, radar, forecasts" to "തത്സമയ കാലാവസ്ഥ, മഴ, മഞ്ഞ്, മൂടൽമഞ്ഞ്, റഡാർ, പ്രവചനങ്ങൾ",
        "Met Office API key" to "Met Office API കീ",
        "Needs Live weather switched on above" to "മുകളിൽ തത്സമയ കാലാവസ്ഥ ഓണാക്കണം",
        "Off leaves more room for Recent places" to "ഓഫ് ആണെങ്കിൽ സമീപകാല സ്ഥലങ്ങൾക്ക് കൂടുതൽ ഇടം",
        "Optional, UK. Free plan: 360 requests a day (the app asks every 10 minutes at most)" to "ഐച്ഛികം, UK. സൗജന്യ പ്ലാൻ: ദിവസം 360 അഭ്യർത്ഥനകൾ (ആപ്പ് പരമാവധി 10 മിനിറ്റിൽ ഒരിക്കൽ ചോദിക്കും)",
        "Puts your TomTom, Mapbox and Met Office keys in the backup file, so Restore brings them back. The file is plain text: keep it somewhere safe" to "നിങ്ങളുടെ TomTom, Mapbox, Met Office കീകൾ ബാക്കപ്പ് ഫയലിൽ ചേർക്കുന്നു, അതിനാൽ പുനഃസ്ഥാപിക്കുക അവ തിരികെ കൊണ്ടുവരും. ഫയൽ സാധാരണ ടെക്സ്റ്റാണ്: സുരക്ഷിതമായി സൂക്ഷിക്കുക",
        "Rain falling on the map, heavier in a downpour or storm" to "മാപ്പിൽ പെയ്യുന്ന മഴ, പെരുമഴയിലോ കൊടുങ്കാറ്റിലോ ശക്തമായി",
        "Rain on the map" to "മാപ്പിൽ മഴ",
        "Saved as" to "ഈ പേരിൽ സംരക്ഷിച്ചു",
        "Snow falling on the map" to "മാപ്പിൽ പെയ്യുന്ന മഞ്ഞ്",
